export default [{"id":713,"question":"قنت كثيرٌ من مساجدنا في الشهر الماضي، فما الصحيح في القنوت؟ هل هو خاصٌّ بالفجر أو الأوقات كلها؟","title":"هل القنوت خاصٌّ بالفجر أو الأوقات كلها؟","answer":"الجواب: القنوت فعله النبيُّ في الأوقات كلها عليه الصلاة والسلام، القنوت في النوازل ثبت في الصحيح أنه فعله في الفجر والظهر والمغرب والعشاء: من حديث أنس، وحديث البراء بن عازب، وجاء من حديث ابن عباس رضي الله عنهما أنه فعله في الأوقات الخمسة كلها، القنوت على الأعداء، الدعاء على الأعداء هذا يُسمَّى: قنوت النوازل، ولكن أفضل ذلك أن يكون في الفجر؛ لأنَّ غالب فعل النبي في الفجر عليه الصلاة والسلام، فإن دعا في المغرب أو في العشاء أو في الظهر أو العصر فلا بأس، لكن بقدر الحاجة، لا يستمر، بقدر الحاجة: أيامًا أو شهرًا، ثم يدع، ثم إذا عاد الأمر -عاد الحدث أو استمر نشاط العدو- أُعيد أيضًا القنوت في النوازل، هذا مشروعٌ، فعله النبيُّ، وفعله الصحابة  وأرضاهم، ويُسمَّى: قنوت النوازل.\nأما قنوت الوتر: فهذا في الوتر في الليل، إذا صلى الركعة الأخيرة قنت فيها بعد الركوع: اللهم اهدنا فيمَن هديتَ .. إلى آخره. وأما ما يفعله بعضُ الناس من القنوت في الفجر دائمًا فهذا الصحيح خلافه، الصحيح أنه غير مشروعٍ، وإن فعله جماعة، واختاره بعضُ الأئمة: كمالك والشافعي رحمهما الله وجماعة، وفعله بعض الصحابة، لكن الأفضل تركه؛ لأنه ثبت من حديث سعد بن طارق الأشجعي أنه قال: قلت لأبي: يا أبت، إنك صليتَ خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي، أفكانوا يقنتون في الفجر؟ فقال: أي بني مُحْدَثٌ. هذا يدل على أنَّ الغالب عليهم عدم فعله، وأنه إنما يفعلونه في النوازل.\nفالأولى والأفضل للمؤمنين ألا يفعلوا هذا القنوت في الفجر، وإنما هو في الوتر، إلا في النوازل: كالدُّعاء للمُجاهدين الأفغان، والمجاهدين في سبيل الله في كل مكانٍ في بعض الأوقات.","link":"https://binbaz.org.sa/fatwas/20572/هل-القنوت-خاص-بالفجر-او-الاوقات-كلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0526فتاوى المحاضرات للشيخ عبدالعزيز بن باز رحمه الله.mp3","categories":["القنوت في الصلاة"]},{"id":1063,"question":"لقد كنتُ في أحد البلاد الإسلامية، ووجدتُهم يقنتون في صلاة الفجر، فهل أقنتُ معهم، علمًا بأنني مُقيمٌ عندهم عدَّة أيام؟","title":"أصلي مع قوم يقنتون في الفجر فهل أقنت معهم؟","answer":"الجواب:\nنعم، صلِّ معهم، واقنت معهم؛ لأنها شبهة، قال به جماعةٌ من العلماء: كالشافعية، والمالكية، صلِّ معهم، وانصحهم وبيِّن لهم أنَّ هذا القنوت ليس مشروعًا على الصحيح، وأن الصواب تركه، إلا في أوقات النَّوازل، كما في حديث طارق بن أشيم عند أهل السنن -عند أحمد وأهل السنن إلا أبا داود- يقول سعد بن طارق: قلتُ لأبي: يا أبتي، صليتَ خلف رسول الله ﷺ، وخلف أبي بكر، وعمر، وعثمان، وعلي، أفكانوا يقنتون في الفجر؟ فقال: \"أي بُني، مُحْدَثٌ\". هذا هو الصواب، ليس بمشروعٍ، لكنَّ بعض أهل العلم رآه مشروعًا، واحتجُّوا بحديثٍ عن أنسٍ: أنه ﷺ كان يقنت حتى فارق الدنيا، ولكنه حديثٌ ضعيفُ الإسناد، فتعلَّق به بعضُ أهل العلم، فإذا قنت معهم فلا حرج عليه؛ مُتابعةً لهم، مع النَّصيحة والتَّوجيه حيث أمكن ذلك.","link":"https://binbaz.org.sa/fatwas/21120/اصلي-مع-قوم-يقنتون-في-الفجر-فهل-اقنت-معهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0916حكم القنوت كل يوم في صلاة الفجر؟ ابن باز فتاوى المحاضرات.mp3","categories":["القنوت في الصلاة"]},{"id":2350,"question":"بالنسبة لدعاء القُنوت: هل يُدعى في صلاة الفجر؟","title":"هل دعاء القنوت يكون في صلاة الفجر؟","answer":"الجواب:\nلا، السنة أن يقنت في الوتر، والدعوة على الأعداء، أمَّا في الفجر فليس هناك قنوتٌ.","link":"https://binbaz.org.sa/fatwas/22475/هل-دعاء-القنوت-يكون-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/دعاء القنوت هل يُدعا في صلاة الفجر.mp3","categories":["القنوت في الصلاة"]},{"id":3586,"question":"يشمل (القنوت) المنفرد والمرأة لوحدهم؟","title":"هل يُشرع قنوت النوازل للمنفرد؟","answer":"الجواب: في النوازل؛ إذا نزل بالمسلمين نازلة، عدو، يقنت يدعو بأن الله ينصر دينه، وأن الله يكفيهم شر العدو، كما كان النبي ﷺ يفعل، الغالب في الفجر، وربما فعله في المغرب، وربما فعله في بقية الأوقات، عليه الصلاة والسلام، هذا يسمى قنوت النوازل.","link":"https://binbaz.org.sa/fatwas/23768/هل-يشرع-قنوت-النوازل-للمنفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/القنوت عند النوازل هل يشمل المنفرد والمرأة.mp3","categories":["القنوت في الصلاة"]},{"id":3587,"question":"الدعاء في رمضان في القيام في كل يوم هل هو سُنة؟","title":"حكم الدعاء في رمضان في القيام كل ليلة","answer":"الجواب: هذا قنوت الوتر الذي جاء في حديث الحسن .","link":"https://binbaz.org.sa/fatwas/23769/حكم-الدعاء-في-رمضان-في-القيام-كل-ليلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الدعاء في رمضان في القيام في كل يوم.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":4591,"question":"إذا داوم على القنوت في الوتر؟","title":"حكم المداومة على قنوت الوتر والتطويل فيه؟","answer":"الجواب: الذي أوصى به النبيُّ ﷺ الحسن: علَّمه ﷺ القنوت: اللهم اهدني فيمَن هديتَ، وعافني فيمَن عافيتَ، وتولَّني فيمَن تولَّيتَ، وبارك لي فيما أعطيتَ، وقني شرَّ ما قضيتَ، فإنك تقضي ولا يُقضى عليك، فإنه لا يذلُّ مَن واليتَ، ولا يعزُّ مَن عاديتَ، تباركتَ ربنا وتعاليت.\nوكان النبي ﷺ يقول في آخر وتره:  اللهم إني أعوذ برضاك من سخطك، وبمُعافاتك من عقوبتك، وأعوذ بك منك، لا أُحصي ثناءً عليك أنت كما أثنيتَ على نفسك خرَّجهما الخمسة: أحمد وأهل السنن.\nفهذا يدل على شرعية قنوت الوتر، وأن يقول هذا الدعاء، وحديث الحسن ثابت، وحديث عليٍّ ثابت أيضًا، وهو يدل على شرعية القنوت.\nوكان بعضُ السلف من الصحابة وغيرهم لا يقنتون إلا في النصف الأخير من رمضان، والصواب أنه مشروع دائمًا في الوتر: في رمضان وفي غيره؛ لحديث الحسن وما جاء في معناه.\nأما زيادة \"ولا يعزُّ مَن عاديتَ\" فالمؤلف ذكرها هنا، وذكر الحافظُ رحمه الله وجماعة أنها في بعض نسخ أبي داود، وذكرها البيهقي رحمه الله، وليست عند الترمذي وابن ماجه وأحمد والنَّسائي، والمؤلف ذكرها هنا لأنها جاءت عند أبي داود في بعض النُّسخ.\nس: بالنسبة لإطالة القنوت والأدعية في هذه الأيام، ما رأيكم فيه؟\nج: لا بأس أن يزيد، ولكن ينبغي أن يُراعي عدم الطول، لا يشقّ على الناس، لو زاد دعوات لا بأس، لكن لا يشقّ على الناس؛ ولهذا كان عمر يزيد: \"اللهم إنا نستعينك ونستهديك ..\" إلى آخره، فإذا زاد بعض الدَّعوات لكن يُراعي عدم المشقَّة.","link":"https://binbaz.org.sa/fatwas/24880/حكم-المداومة-على-قنوت-الوتر-والتطويل-فيه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/المداومة على القنوت في الوتر والتطويل فيه.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":4936,"question":"بعض الناس يقول: المسلمون الآن في حاجة مستمرة فالدعاء في الفجر يكون بشكل مستمر؟","title":"هل يداوم على القنوت في الفجر بحجة كثرة النوازل؟","answer":"الجواب: لا، ما هو مشروع إلا إذا نزل حوادث، أما عداوة الكفار للمسلمين من عهد النبي موجودة ومستمرة.\nس: الزلازل والبراكين؟\nالشيخ: لا، المعروف نزول العدو الكافر.","link":"https://binbaz.org.sa/fatwas/27040/هل-يداوم-على-القنوت-في-الفجر-بحجة-كثرة-النوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجوز استمرار القنوت لكثرة النوازل.mp3","categories":["القنوت في الصلاة"]},{"id":4937,"question":"قنوت النوازل يشرع للمنفرد؟","title":"هل يُشرع قنوت النوازل للمنفرد؟","answer":"الجواب: نعم ما أعلم فيه مانعًا.","link":"https://binbaz.org.sa/fatwas/27039/هل-يشرع-قنوت-النوازل-للمنفرد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يُشرع قنوت النوازل للمنفرد.mp3","categories":["القنوت في الصلاة"]},{"id":5539,"question":"قول: \"اللهم اهدني فيمن هديت\" هل قنت ﷺ بهذا القنوت؟","title":"هل ثبت دعاء قنوت الوتر في السُّنة؟","answer":"الجواب: لا، ما قنت، إنما يقنت يدعو على قومٍ، أو لقومٍ، أما هذا: علَّمه النبيُّ ﷺ للحسن في القنوت، ثم كان ﷺ إذا دعا وهو إمام ما يقول بالإفراد، يقول بالجمع، إذا دعا للمسلمين يجمع، وإنما يقول: \"اهدني، واغفر لي\" إذا كان وحده عليه الصلاة والسلام، وإذا كان في صلاته يدعو لنفسه فيما بينه وبين ربه، كما يقول في السجود: اللهم اغفر لي ذنبي كله، دقه وجله، أما الدعاء العام في الخطب والقنوت فهذا يعمّ: \"اللهم اغفر لنا، اللهم ارحمنا، اللهم أنجنا، اللهم انصرنا\"، ونحو ذلك.[1]","link":"https://binbaz.org.sa/fatwas/31472/هل-ثبت-دعاء-قنوت-الوتر-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 001.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":5541,"question":"بعض الناس المقلّدين إذا صلَّى وراء مَن لا يقنت يتأخَّر ويقنت في نفسه ويترك الإمامَ يسجد؟","title":"ما حكم مَن تأخرعن الإمام ليقنت لنفسه؟","answer":"الجواب: لا، ما ينبغي هذا: إنما جُعل الإمامُ ليُؤتمَّ به، فلا تختلفوا عليه، إذا صلَّى خلف مَن لا يقنت يفعل مثله، يسجد معه، وليترك القنوت؛ لأنَّ القنوت لا أصلَ له في الدوام، إنما هو في النوازل، النبي ما كان يستمرّ عليه. س: وإذا قنت الإمامُ؟ ج: إذا قنت معه فلا بأس؛ لأنه له شبهة مذهب الشافعي وجماعة.[1]","link":"https://binbaz.org.sa/fatwas/31477/ما-حكم-من-تاخرعن-الامام-ليقنت-لنفسه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 004.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":5543,"question":"القنوت في النَّوازل أصبح من السنن المهجورة؟","title":"ما حكم القنوت في النَّوازل؟","answer":"الجواب: بعض أهل العلم يرى أنه منسوخ، ولكن ما هو بصحيح؛ لأنَّ الله جلَّ وعلا قال: لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ [آل عمران:128] لما قنت، والصواب أنه ليس بمنسوخٍ، وإنما بيَّن له الرب جلَّ وعلا أنَّ عليه فعل الأسباب، وعليه الدعاء، والله هو الهادي ، فقد دعا على قومه فلم يستجب له فيهم، وهداهم الله، وأنزل: لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ، مثل: الحارث بن هشام، وصفوان بن أمية، والأظهر بقاؤه في النوازل، ولكن مثلما قال ..... قلَّما يفعله، قال: والقنوت في مثل نازلة جهاد الأفغان وبعض النوازل الأخرى جديرٌ فيها الدُّعاء.[1]","link":"https://binbaz.org.sa/fatwas/31478/ما-حكم-القنوت-في-النوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/zad almaad 005.mp3","categories":["القنوت في الصلاة"]},{"id":7008,"question":"ما حكم الصلاة خلف من يذهب إلى قبور الصالحين؛ للتبرك بها، وتلاوة القرآن في الموالد وغيرها بأجر على ذلك؟","title":"حكم الصلاة خلف من يذهب إلى قبور الصالحين","answer":"الجواب: \n\nهذا فيه تفصيل، إن كان مجرد الاحتفال بالموالد من دون شرك، هذا مبتدع، فينبغي ألا يكون إمامًا، وصلاته صحيحة.\n\nوأما إذا كان يدعو الأموات، ويستغيث بالأموات، ويدعوهم: يا رسول الله، يا فلان، يا سيدي البدوي، يا سيدي حسين، يا فلان، المدد المدد، يا سيدي عبدالقادر، هذا مشرك، ما يصلى خلفه -نسأل الله العافية-.\n\nأما إذا كان بدعة، يحضر المولد، ولكن ما يأتي بالشرك، أو يقرأ القرآن عند القبور، ولا يأتي بشرك، هذا يكون عنده بدعة، يعلم، يوجه، وصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/2947/حكم-الصلاة-خلف-من-يذهب-الى-قبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1397.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7018,"question":"ما حكم الصلاة خلف من يذهب إلى قبور الصالحين؛ للتبرك بها، وتلاوة القرآن في الموالد وغيرها بأجر على ذلك؟","title":"حكم الصلاة خلف من يذهب إلى قبور الصالحين","answer":"الجواب: \n\nهذا فيه تفصيل، إن كان مجرد الاحتفال بالموالد من دون شرك، هذا مبتدع، فينبغي ألا يكون إمامًا، وصلاته صحيحة.\n\nوأما إذا كان يدعو الأموات، ويستغيث بالأموات، ويدعوهم: يا رسول الله، يا فلان، يا سيدي البدوي، يا سيدي حسين، يا فلان، المدد المدد، يا سيدي عبدالقادر، هذا مشرك، ما يصلى خلفه -نسأل الله العافية-.\n\nأما إذا كان بدعة، يحضر المولد، ولكن ما يأتي بالشرك، أو يقرأ القرآن عند القبور، ولا يأتي بشرك، هذا يكون عنده بدعة، يعلم، يوجه، وصلاته صحيحة.","link":"https://binbaz.org.sa/fatwas/2947/حكم-الصلاة-خلف-من-يذهب-الى-قبور-الصالحين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1397.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7039,"question":"في بعض البلاد الإسلامية يقنتون في الركعة الثانية وبعد الاعتدال من الركوع في صلاة الفجر من كل يوم وبصفة مستمرة، هل هذا مطابق للسنة؟ وإنني أحضر للصلاة معهم في بعض الأوقات، فهل هذا يؤثر في صلاتي؟","title":"هل الاستمرار على القنوت في الفجر من السنة؟","answer":"الجواب:\n\nهذا ذهب إليه بعض العلماء كالشافعي رحمه الله وجماعة وظنوا واعتقدوا أنه سنة لأحاديث ضعيفة وردت في ذلك، والصواب: أنه ليس بسنة دائمة بل يفعل عند الحاجة، عند حاجة هجوم العدو أو الدعاء على العدو، بعض الأحيان النبي ﷺ فعله تارة وتركه تارة عليه الصلاة والسلام وهو القنوت في صلاة الفجر. \n\nفالذي ينبغي أنه لا يداوم عليه، ولكن إذا كان مع جماعة يداومون يصلي معهم لا يخلي الصلاة، يصلي معهم وينصح الإمام، يقول له: الأفضل والسنة لك أنك تفعله تارة إذا كان يدعو على قوم من الكفار، يقول سعد بن طارق بن أشيم الأشجعي يقول: سألت أبي طارق -وأبوه من الصحابة- ...\n\nلكن إذا كان يدعو على الشيوعية والكفرة، ويدعو الله للمجاهدين الأفغان ونحوهم أن ينصرهم الله هذا من القنوت في النوازل، يعني هذا يسمى قنوات النوازل عند الحاجة، وإن فعله في المغرب أو في العشاء صح.","link":"https://binbaz.org.sa/fatwas/3009/هل-الاستمرار-على-القنوت-في-الفجر-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1416.mp3","categories":["البدع والمحدثات","صلاة الجماعة","القنوت في الصلاة"]},{"id":7241,"question":"هل دعاء الإمام، وتأمين المصلين بعد الفريضة من البدع؟ وهل يجوز رفع اليدين في دعاء القنوت؟","title":"حكم الدعاء بعد الفريضة ورفع اليدين في القنوت","answer":"الجواب:\n\nكون الإمام يدعو بعد الفرائض الخمس، ويؤمن على الدعاء؛ هذا بدعة، ما له أصل، ما كان النبي ﷺ يفعله، ولا أصحابه، إذا سلم الإمام والمأموم كل يشتغل بذكر الله -جل وعلا-.\n\nأما كون الإمام يرفع يديه، ويدعو، ويؤمنون؛ هذا ما له أصل، هذا من البدع.\n\nأما القنوت مشروع، رفع اليدين في القنوت مشروع، وقد ثبت عن النبي ﷺ أنه رفع يديه في القنوت، في النوازل، والقنوت في الوتر مثله، مثل القنوت في النوازل.","link":"https://binbaz.org.sa/fatwas/3304/حكم-الدعاء-بعد-الفريضة-ورفع-اليدين-في-القنوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk7_1629.mp3","categories":["صلاة الجماعة","القنوت في الصلاة"]},{"id":7861,"question":"أيضاً يقول في رسالته: هل من لوازم صلاة الوتر القنوت وهل ورد عنه ﷺ أنه صلى الوتر بدون قنوت؟","title":"هل يلزم القنوت في صلاة الوتر؟","answer":"الجواب: ليس من اللوازم القنوت، مستحب القنوت، الوتر مستحب والقنوت مستحب، قد علمه النبي ﷺ الحسن بن علي فهو مستحب وليس بفرض، ولا نعلم أنه ﷺ داوم على القنوت كما أننا لا نعلم أنه تركه تارة وفعله تارة، لكن فعله الصحابة تارة وتركوه تارة، أبي بن كعب لما أم الناس في عهد عمر كان يتركه تارة ويقنت تارة، فلا حرج في تركه؛ لأنه نافلة، إذا تركه بعض الأحيان فلا بأس. نعم.","link":"https://binbaz.org.sa/fatwas/5273/هل-يلزم-القنوت-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_056/05601.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":8096,"question":"هذه رسالة وردتنا من محمد صالح محمد من الدمام يقول: ما حكم قراءة دعاء القنوت في كل ليلة في بعد الوتر؟","title":"حكم المداومة على دعاء القنوت في الوتر","answer":"الجواب: لا حرج في ذلك، دعاء القنوت سنة، كان النبي ﷺ يقنت، وقد علم الحسن كلمات القنوت في الوتر فهو سنة، فإذا قرأت في كل ليلة فلا بأس، وإن تركه بعض الأحيان حتى يعلم الناس أنه ليس بواجب، فهذا لا بأس به، إذا ترك الإمام القنوت بعض الأحيان، ليعلم الجماعة أنه ليس بواجب فهذا لا بأس، وإذا استمر فلا بأس، النبي ﷺ لما علم الحسن القنوت ما قال له: دعه في بعض الأيام، فدل ذلك على أنه إذا استمر فلا حرج. نعم.\nالمقدم: شكراً أثابكم الله.","link":"https://binbaz.org.sa/fatwas/5894/حكم-المداومة-على-دعاء-القنوت-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_086/08609.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":8211,"question":"سؤاله الثالث: أصلي بجماعة وهم يصرون على قراءة دعاء القنوت في الركعة الأخيرة من صلاة الصبح، إلا أن يقيني في هذا الدعاء وحسب علمي من بعض المصادر الصحيحة أن الرسول ﷺ كان يقرأه في الركعة الأخيرة من صلاة الصبح عند الابتلاءات فقط، فهل أعمل برأيهم وأخالف السنة، أم أعمل برأيي فأصيب السنة، أم أتنازل عن الإمامة تفادياً للخلاف، أفيدونا أفادكم الله؟","title":"هل من السنة المداومة على القنوت في صلاة الصبح؟","answer":"الجواب: عليك أن تعمل بالسنة وأن تنبههم على هذا، وترشدهم إلى ذلك بالأسلوب الحسن، فإن القنوت دائماً في الفجر ليس من المشروع، بل هو محدث، ثبت في مسند أحمد رحمه الله وسنن الترمذي و النسائي وابن ماجة عن سعد بن طارق بن أشيم الأشجعي، عن أبيه أن سعداً قال: يا أبت! إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر و عمر وعثمان وعلي -رضي الله عن الجميع- أفكانوا يقنتون في الفجر؟ فقال: أي بني! محدث فبين طارق أن هذا محدث.\nوثبت من حديث أنس ومن حديث غير أنس كـأبي هريرة وجماعة أنه صلى الله عليه وسلم: كان يقنت في النوازل في الصبح وغيرها، فإذا وقع ابتلاء من عدو وقع بالمسلمين أو نزل بالمسلمين، أو سرية قتلت بالمسلمين، أو ما أشبه ذلك، يدعو الأئمة في المساجد في الركعة الأخيرة من الفجر، بعد الركوع بقدر النازلة أياماً أو شهراً أو نحو ذلك، ثم يمسكون، ما يستمرون هذا السنة عند الحاجة والنازلة يدعى ويقنت، لكن من غير استمرار، أما الاستمرار دائماً دائماً فهذا خلاف السنة، فعليك أن تقنعهم وأن توجههم إلى الخير، فإذا لم يقنعوا ولم يحصل من التئام بينك وبينهم، فلا مانع من الانتقال عنهم إلى مسجد آخر وعدم مخالفة السنة.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/6019/هل-من-السنة-المداومة-على-القنوت-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_095/09505.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":8497,"question":"أختنا تقول: ما حكم من نسي دعاء القنوت في صلاة الوتر وسجد قبل أن يدعو به، وهل يجبره سجود السهو؟","title":"حكم من نسي قنوت الوتر","answer":"الجواب: ليس عليه شيء من نسي قنوت الوتر فلا شيء عليه، ولا يلزمه سجود السهو، فإن سجد فلا بأس ولكن لا يلزمه؛ لأن قنوت الوتر مستحب وليس بواجب وإذا تركه بعض الأحيان عمداً فلا بأس، كما فعله الصحابة  فالأمر في هذا واسع والحمد لله. نعم.","link":"https://binbaz.org.sa/fatwas/6557/حكم-من-نسي-قنوت-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_126/12611.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":8520,"question":"له سؤال آخر في هذه الرسالة يقول فيه: ما حكم دعاء القنوت في صلاة الصبح، وهل يوجب تركه سجود السهو، وإذا لم نسجد للسهو، هل تعتبر الصلاة صحيحة؟","title":"حكم القنوت في صلاة الصبح","answer":"الجواب: أولاً القنوت في الصبح غير مشروع على وجه الدوام، بل هو غير مشروع، بل أقل أحواله أن يكون مكروهاً، وظاهر النصوص أنه بدعة؛ ولهذا ثبت في حديث سعد بن طارق الأشجعي عن أبيه أنه سأل أباه، قال: يا أبت! إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر وعمر وعثمان وعلي ، أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث قال طارق لابنه: أي بني محدث، وطارق من أصحاب النبي ﷺ، رواه أحمد رحمه الله والترمذي والنسائي وابن ماجة بإسناد جيد، فهذا يدل على أنه غير مشروع القنوت في الصبح، هذا القنوت الدائم، فهو محدث لم يفعله الرسول ﷺ ولا أصحابه، يعني: ولا الخلفاء المذكورون.\nوذهب قوم من أهل العلم إلى أنه يستحب كـالشافعي رحمه الله وجماعة، واحتجوا بحديث جاء عن أنس أن النبي ﷺ كان يقنت في الصبح حتى فارق الدنيا لكنه حديث ضعيف عند أهل العلم ليس بثابت، والصواب أن القنوت في الصبح إنما هو في النوازل خاصة، إذا نزل بالمسلمين نازلة مثل الحروب التي يشنها الأعداء فيشرع القنوت، كما قنت النبي ﷺ شهراً يدعو على أحياء من العرب؛ لما قتلوا جماعة من أصحابه ، وقنت يدعو على قريش مدة من الزمن، هذا لا بأس به، هذا مشروع عند الحاجة إليه، لكن ليس بدائم بل مؤقت شهر شهرين ثم يتركه، هذا مشروع للنوازل والحاجة التي تعرض من عدوان على المسلمين من عدوهم، فيقنت في الدعاء عليهم كما فعله المصطفى صلى الله عليه وسلم، أما القنوت الدائم في الصبح أو في غيرها فهذا غير مشروع بل هو بدعة، وأقل أحواله أن يكون مكروهاً؛ لأنه خلاف الأحاديث الصحيحة، والله المستعان. نعم.\nالمقدم: جزاكم الله خير، وبارك الله فيكم، يقول في سؤال ثالث في هذه الرسالة الأخ حسن عبد الستار أبو زيد : هل يجوز أن أصلي على قبر أبي صلاة الجنازة عند زيارته طلباً للرحمة له، وهل إذا ...\nالشيخ: أعد السؤال.\nالمقدم: يقول: هل يجوز لي أن أصلي على قبر أبي.\nالشيخ: هذاك الأول له بقية سؤال.\nالمقدم: نعم سؤاله الأول.\nالشيخ: وهو سجود السهو إذا تركوه، إذا ترك القنوت لا يسجد للسهو؛ لأنه مستحب فقط، لا يجب له سجود السهو، إذا ترك القنوت في النوازل لا يسجد له، أما في غير النوازل فعرفت أنه مكروه أو بدعة فلا يسجد له، بل تركه هو الذي ينبغي، وإذا لم يسجدوا كذلك لا حرج، صلاتهم صحيحة حتى ولو كان مشروعاً في النوازل، لو تركوا السجود.. لو تركوه سهواً فلا سجود له، ولا حرج عليهم في ذلك، وإذا تركوا سجود السهو ..، القنوت الذي تركوه فهو غير ..... لصلاتهم، وصلاتهم صحيحة، إذا قلنا: إن القنوت مستحب للنوازل، وأما في غير النوازل كالقنوت الدائم في الصبح هذا مكروه أو بدعة، فلا سجود له إذا ترك، بل تركه هو الصواب. نعم.","link":"https://binbaz.org.sa/fatwas/6586/حكم-القنوت-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_203/20303.mp3","categories":["القنوت في الصلاة"]},{"id":9076,"question":"يتحدث الناس كثيراً سماحة الشيخ عن صلاة النساء للتهجد أو التراويح في المساجد هل من كلمة حول هذا لو تكرمتم؟","title":"حكم خروج النساء لصلاة التراويح","answer":"الجواب: نعم، لا بأس بذلك أن يصلي النساء مع المسلمين في المساجد لكن مع العناية بالحجاب والتحرز من الفتنة وعدم الأطياب التي يمرون بها في الأسواق، تكون متحرزة من الطيب ومن التبرج وإظهار المحاسن، بل تكون محتجبة متسترة بعيدة عن أسباب الفتنة وإلا فبيتها خير لها، بيتها أولى بها وأكرم لها، لكن إذا دعت الحاجة إلى الخروج؛ لأنها تكسل في بيتها أو لأنها تريد أن تسمع المواعظ والذكر فهذا لا بأس به لكن بهذا الشرط؛ التحفظ والعناية والتستر والبعد عن أسباب الفتنة لا من جهة الطيب ولا من جهة الملابس ولا من جهة إظهار المحاسن. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7235/حكم-خروج-النساء-لصلاة-التراويح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_149/14912.mp3","categories":["قضايا المرأة","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":9406,"question":"من اليمن الشمالي، الحديدة هذه رسالة بعث بها أخونا عبده أبو الغيث مشهور، أخونا يسأل في رسالته عن قضيتين، الأولى يقول: إن أناسًا يدعون بدعاء القنوت في الركعة الثانية من الصبح، وأناس آخرون يدعون في الركعة الثالثة من الوتر؛ لأنهم يصلون الوتر ثلاثًا، ولكنهم يقولونه بعد الرفع من الركوع، فمن هم الذين على الطريق الصحيح، نرجو إفادتنا؟","title":"هل القنوت في الوتر أم في صلاة الفجر؟","answer":"الجواب: الوتر مشروع، ويشرع فيه القنوت، ومحله ما بين صلاة العشاء إلى طلوع الفجر، يعني: جميع الليل من بعد صلاة العشاء إلى طلوع الفجر، هذا محل الوتر، فإذا صلى واحدة ورفع من الركوع شرع له أن يدعو بالقنوت: اللهم اهدنا فيمن هديت.. إلى آخره. وإن كان إمام جماعة قال: اللهم اهدنا فيمن هديت وعافنا.. إلى آخره.\nأما الفجر فلا يشرع فيها القنوت إلا لعلة؛ نازل من النوازل -الفجر- كان النبي ﷺ يقنت فيها وفي غيرها من الفرائض في النوازل، إذا وقع عدوان من بعض الناس على المسلمين أو حصروا بلاد المسلمين كان النبي ﷺ يقنت في الفرائض يدعو عليهم، والغالب أنه يقنت في الفجر في الركعة الأخيرة، بعدما يرفع رأسه من الركوع يقنت ويدعو على العدو، وقد فعل هذا كثير عليه الصلاة والسلام، وربما استمر شهرًا وربما استمر أربعين يومًا وربما كان ذلك أقل، ثم يمسك فيستمر، فإذا دعا الإنسان أو المسلمون في صلاة الفجر أو غيرها في الركعة الأخيرة بعد الركوع إذا دعوا للمسلمين مثل المجاهدين الأفغان دعوا لهم بالنصر، وعلى عدوهم بالهزيمة فلا بأس، لكن لا يستمر تارة وتارة حتى يحصل النصر.\nأما ما يفعله بعض الناس من الاستمرار في القنوت في الفجر دائمًا دائمًا ولو من دون نزول نازلة فهذا مكروه ولا ينبغي بل بدعة على الصحيح من أقوال العلماء؛ لأن الرسول ﷺ لم يفعله بصورة مستمرة، وإنما كان يفعله للأسباب التي ذكرنا وهي وجود نازلة تنزل بالمسلمين تضرهم.\nويدل على هذا المعنى ما ثبت في الحديث الصحيح من رواية سعد بن طارق بن أشيم الأشجعي عن أبيه أنه قال لأبيه طارق: يا أبت! صليت خلف رسول الله ﷺ، وخلف أبي بكر ، وخلف عمر ، وخلف عثمان ، وخلف علي هاهنا في الكوفة، أفكانوا يقنتوا في الفجر؟ فقال له أبوه: أي بني محدث أي بني، يعني: يا بني محدث، يعني: محدث القنوت في الفجر، يعني: لغير النوازل، قد رواه أحمد رحمه الله في مسنده والترمذي والنسائي وابن ماجة وغيرهم بإسناد صحيح عن سعد بن طارق الأشجعي عن أبيه.\nفهذا الحديث الصحيح حجة ظاهرة على عدم شرعية القنوت في الفجر بصفة مستمرة، وإنما يشرع في الفجر وغيرها إذا وجد نازلًا بالمسلمين مثل نازلة الأفغان فلا بأس أن يدعى بل يشرع أن يدعى بين وقت وآخر، هذا هو المشروع.\nوذهب بعض أهل العلم إلى أنها تستحب في صلاة مطلقًا، وهو قول له شبهة في قنوت النبي ﷺ في النوازل، فظنوا أنه يستحب دائمًا، وتعلقوا بأحاديث ضعيفة جاءت فيه: أنه لم يزل يقنت في الفجر حتى فارق الدنيا ولكنها أحاديث ضعيفة لا تصح عن النبي ﷺ، فظنها من ظنها صحيحة فعمل بها.\nفالذي ينبغي ترك ذلك؛ لأن حديث سعد بن طارق عن أبيه صحيح صريح في ذلك فينبغي للأئمة في مثل هذا أن لا يفعلوه إلا بصفة خاصة في النوازل. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7570/هل-القنوت-في-الوتر-ام-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_189/18902.mp3","categories":["القنوت في الصلاة"]},{"id":9438,"question":"وهذه رسالة وردت إلينا من السائل (ن-ع) من حمص من سورية، الأخ السائل في رسالته سؤال طويل في الحقيقة مقتضاه الاستفسار عن سبب الاختلاف بين كثير من المفتين فيما يعرف بالقنوت في صلاة الصبح، والسائل يذكر أنه قرأ في كتاب نور اليقين في سيرة سيد المرسلين ﷺ للشيخ محمد الخضري بأن مشركي مكة منعوا بعضاً من المسلمين عن الهجرة وحبسوهم وعذبوهم منهم: الوليد بن الوليد ، وعياش بن ربيعة ، فكان النبي ﷺ يدعو لهم في صلاته، وهذا أصل القنوت، وقد حصل في أوقات مختلفة، فكان في وتر العشاء وفي صلاة الصبح بعد الركوع وقبله، وروى الصحابة كل منهم ما رآه، وهذا سبب اختلاف الأئمة ، هكذا قرأ في كتاب سيرة سيد المرسلين، ثم ينقل بعد ذلك بأن هناك كلاماً لبعض أهل العلم في جواز ذلك وفي منعه، فيسأل عن الحكم الصحيح، وعن سبب هذا الاختلاف؟","title":"ما سبب الاختلاف في القنوت في صلاة الصبح؟","answer":"الجواب: القنوت نوعان: نوع يسمى القنوت في النوازل، وهذا مشروع ومندوب وفعله النبي ﷺ، فإنه قنت على رعل وذكوان لما قتلوا القراء، وكذلك قنت على أهل مكة ولعن الحارث بن هشام، وسهيل بن عمرو، وصفوان بن أمية، فأنزل الله: لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ [آل عمران:128].\nفهو يقنت في النوازل عليه الصلاة والسلام يدعو على المشركين الذين قاتلوه، أو قتلوا بعض أصحابه، أو آذوا المسلمين، فالقنوت في النوازل مشروع لإظهار غضب المسلمين على أعدائهم، ولسؤال الله  الانتقام منهم، مما فعلوا بالمسلمين، هذا هو القنوت في النوازل، وهذا مؤقت، يقنت النبي ﷺ شهراً، أو أقل أو أكثر ثم يترك فهو قنوت مؤقت لأسباب حادثة، هذا مشروع إلى اليوم ولا حرج فيه، كأن يقنت اليوم في الدعاء على السوفيت؛ لأنهم ظلموا الأفغانيين، وتعدوا عليهم فيقنت للدعاء عليهم، وفي الدعاء للمجاهدين الأفغان بالنصر؛ لأنهم مجاهدون في سبيل الله  فيدعى لهم بالنصر ولعدوهم بالخذلان والقضاء عليه، وكأن يدعى على اليهود لتعديهم وظلمهم لأهل فلسطين، يدعى عليهم بأن الله يخذلهم، ويسلط عليهم ويبطل كيدهم، وينصر المسلمين عليهم، هذا يسمى القنوت في النوازل، وهذا لا يدوم، تارة وتارة، كما فعله النبي ﷺ وفعله الصحابة.\nأما النوع الثاني: فهو قنوت في الصبح خاصة، هذا اختاره بعض أهل العلم، وقالوا: يقنت في الصبح دائماً، بالدعاء للمسلمين، والدعاء على الكافرين، سواء قرأ فيه: اللهم اهدنا فيمن هديت، أو دعا بدعوات أخرى، واحتجوا على هذا بحديث جاء عن أنس رضي الله عنه: على النبي ﷺ: أنه كان يقنت في الصبح حتى فارق الدنيا يعني: ما زال يقنت في الصبح حتى فارق الدنيا، واحتج بهذا جماعة من أهل العلم كالشافعية وجماعة على شرعية القنوت في الصبح دائماً، وقال آخرون من أهل العلم: لا، لا يشرع دائماً إنما هذا في النوازل، وأما حديث أنس فهو ضعيف، ولو صح فالمراد به: إنه ما زال يطول في الفجر حتى فارق الدنيا، كان يطيل صلاة الفجر، وإطالة القيام والقراءة يسمى قنوت، وقد استدلوا على النهي عن القنوت في الصبح دائماً، استدلوا عليه بما رواه الإمام أحمد والترمذي والنسائي وابن ماجة بإسناد جيد عن سعد بن طارق الأشجعي قال: قلت لأبي: يا أبتِ! إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر وعمر وعثمان وعلي ، أفكانوا يقنتون في الفجر؟ فقال طارق: أي بني محدث.\nفـطارق من أصحاب النبي ﷺ، وأخبر ابنه سعداً أن القنوت في الفجر ليس من عمل النبي ﷺ ولا من عمل الخلفاء الراشدين الأربعة بل هو محدث، فهذه حجة من قال: إنه لا يقنت في الصبح بصفة دائمة، ولكن يقنت في الصبح أو في المغرب أو في العشاء أو في غيرهما بصفة غير دائمة عند الحاجة إلى ذلك، للدعاء على الكفرة، والدعاء للمسلمين، عند وجود العدوان من الكفرة، وعند قيام الحرب ونحو ذلك، هذا هو الأرجح وهذا هو الصواب، أن القنوت يكون في النوازل خاصة، وأما القنوت الدائم في الصبح، فالصحيح: أن الأولى تركه، وأن الذي ينبغي تركه، وأنه محدث وليس من السنن، بل هو من البدع المحدثة، كما قال طارق بن أشيم الأشجعي لابنه سعد قال: أي بني! محدث .\nهذا هو الأرجح من قولي العلماء في هذه المسألة وسبب الخلاف عرفت أيها السائل! أن أسباب الخلاف حديث أنس حيث قال فيه: فأما في الصبح فلم يزل يقنت حتى فارق الدنيا، وهو حديث رواه أحمد وابن حبان وجماعة لكنه ضعيف الإسناد، وحمله بعض أهل العلم على أنه لو صح لكان المراد به طول القيام؛ لأن طول القيام يسمى قنوتاً، والنبي كان يطيل في الفجر عليه الصلاة والسلام، وأما حديث سعد فهو حديث صريح واضح في روايته عن أبيه عن نفس القضية، فقال طارق: أي بني محدث، يعني: ما فعله الرسول ﷺ، ولا خلفاؤه الراشدون الأربعة، فدل ذلك على أنه محدث وليس من المشروع، والله ولي التوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7605/ما-سبب-الاختلاف-في-القنوت-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23906.mp3","categories":["القنوت في الصلاة"]},{"id":9439,"question":"وهذه رسالة وردت إلينا من السائل (ن-ع) من حمص من سورية، الأخ السائل في رسالته سؤال طويل في الحقيقة مقتضاه الاستفسار عن سبب الاختلاف بين كثير من المفتين فيما يعرف بالقنوت في صلاة الصبح، والسائل يذكر أنه قرأ في كتاب نور اليقين في سيرة سيد المرسلين ﷺ للشيخ محمد الخضري بأن مشركي مكة منعوا بعضاً من المسلمين عن الهجرة وحبسوهم وعذبوهم منهم: الوليد بن الوليد ، وعياش بن ربيعة ، فكان النبي ﷺ يدعو لهم في صلاته، وهذا أصل القنوت، وقد حصل في أوقات مختلفة، فكان في وتر العشاء وفي صلاة الصبح بعد الركوع وقبله، وروى الصحابة كل منهم ما رآه، وهذا سبب اختلاف الأئمة ، هكذا قرأ في كتاب سيرة سيد المرسلين، ثم ينقل بعد ذلك بأن هناك كلاماً لبعض أهل العلم في جواز ذلك وفي منعه، فيسأل عن الحكم الصحيح، وعن سبب هذا الاختلاف؟","title":"ما سبب الاختلاف في القنوت في صلاة الصبح؟","answer":"الجواب: القنوت نوعان: نوع يسمى القنوت في النوازل، وهذا مشروع ومندوب وفعله النبي ﷺ، فإنه قنت على رعل وذكوان لما قتلوا القراء، وكذلك قنت على أهل مكة ولعن الحارث بن هشام، وسهيل بن عمرو، وصفوان بن أمية، فأنزل الله: لَيْسَ لَكَ مِنَ الأَمْرِ شَيْءٌ [آل عمران:128].\nفهو يقنت في النوازل عليه الصلاة والسلام يدعو على المشركين الذين قاتلوه، أو قتلوا بعض أصحابه، أو آذوا المسلمين، فالقنوت في النوازل مشروع لإظهار غضب المسلمين على أعدائهم، ولسؤال الله  الانتقام منهم، مما فعلوا بالمسلمين، هذا هو القنوت في النوازل، وهذا مؤقت، يقنت النبي ﷺ شهراً، أو أقل أو أكثر ثم يترك فهو قنوت مؤقت لأسباب حادثة، هذا مشروع إلى اليوم ولا حرج فيه، كأن يقنت اليوم في الدعاء على السوفيت؛ لأنهم ظلموا الأفغانيين، وتعدوا عليهم فيقنت للدعاء عليهم، وفي الدعاء للمجاهدين الأفغان بالنصر؛ لأنهم مجاهدون في سبيل الله  فيدعى لهم بالنصر ولعدوهم بالخذلان والقضاء عليه، وكأن يدعى على اليهود لتعديهم وظلمهم لأهل فلسطين، يدعى عليهم بأن الله يخذلهم، ويسلط عليهم ويبطل كيدهم، وينصر المسلمين عليهم، هذا يسمى القنوت في النوازل، وهذا لا يدوم، تارة وتارة، كما فعله النبي ﷺ وفعله الصحابة.\nأما النوع الثاني: فهو قنوت في الصبح خاصة، هذا اختاره بعض أهل العلم، وقالوا: يقنت في الصبح دائماً، بالدعاء للمسلمين، والدعاء على الكافرين، سواء قرأ فيه: اللهم اهدنا فيمن هديت، أو دعا بدعوات أخرى، واحتجوا على هذا بحديث جاء عن أنس رضي الله عنه: على النبي ﷺ: أنه كان يقنت في الصبح حتى فارق الدنيا يعني: ما زال يقنت في الصبح حتى فارق الدنيا، واحتج بهذا جماعة من أهل العلم كالشافعية وجماعة على شرعية القنوت في الصبح دائماً، وقال آخرون من أهل العلم: لا، لا يشرع دائماً إنما هذا في النوازل، وأما حديث أنس فهو ضعيف، ولو صح فالمراد به: إنه ما زال يطول في الفجر حتى فارق الدنيا، كان يطيل صلاة الفجر، وإطالة القيام والقراءة يسمى قنوت، وقد استدلوا على النهي عن القنوت في الصبح دائماً، استدلوا عليه بما رواه الإمام أحمد والترمذي والنسائي وابن ماجة بإسناد جيد عن سعد بن طارق الأشجعي قال: قلت لأبي: يا أبتِ! إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر وعمر وعثمان وعلي ، أفكانوا يقنتون في الفجر؟ فقال طارق: أي بني محدث.\nفـطارق من أصحاب النبي ﷺ، وأخبر ابنه سعداً أن القنوت في الفجر ليس من عمل النبي ﷺ ولا من عمل الخلفاء الراشدين الأربعة بل هو محدث، فهذه حجة من قال: إنه لا يقنت في الصبح بصفة دائمة، ولكن يقنت في الصبح أو في المغرب أو في العشاء أو في غيرهما بصفة غير دائمة عند الحاجة إلى ذلك، للدعاء على الكفرة، والدعاء للمسلمين، عند وجود العدوان من الكفرة، وعند قيام الحرب ونحو ذلك، هذا هو الأرجح وهذا هو الصواب، أن القنوت يكون في النوازل خاصة، وأما القنوت الدائم في الصبح، فالصحيح: أن الأولى تركه، وأن الذي ينبغي تركه، وأنه محدث وليس من السنن، بل هو من البدع المحدثة، كما قال طارق بن أشيم الأشجعي لابنه سعد قال: أي بني! محدث .\nهذا هو الأرجح من قولي العلماء في هذه المسألة وسبب الخلاف عرفت أيها السائل! أن أسباب الخلاف حديث أنس حيث قال فيه: فأما في الصبح فلم يزل يقنت حتى فارق الدنيا، وهو حديث رواه أحمد وابن حبان وجماعة لكنه ضعيف الإسناد، وحمله بعض أهل العلم على أنه لو صح لكان المراد به طول القيام؛ لأن طول القيام يسمى قنوتاً، والنبي كان يطيل في الفجر عليه الصلاة والسلام، وأما حديث سعد فهو حديث صريح واضح في روايته عن أبيه عن نفس القضية، فقال طارق: أي بني محدث، يعني: ما فعله الرسول ﷺ، ولا خلفاؤه الراشدون الأربعة، فدل ذلك على أنه محدث وليس من المشروع، والله ولي التوفيق.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7605/ما-سبب-الاختلاف-في-القنوت-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_239/23906.mp3","categories":["القنوت في الصلاة"]},{"id":10548,"question":"هل دعاء القنوت في صلاة الفجر بدعة أم سنة؟","title":"القنوت في الفجر غير مشروع، إلا للنوازل","answer":"الجواب: الدعاء في صلاة الفجر دعاء القنوت ليس بمشروع، إلا للأسباب إذا كان هناك أسباب وهي: تسمى أسباب النوازل، يعني: إذا كان هناك نازلة بالمسلمين مثل حرب نزلت بالمسلمين عدو هجم عليهم أو على بعض قراهم يدعى عليه، أو عدو قتل منهم بعضهم كما دعا النبي ﷺعلى من قتل القراء ودعا على أهل مكة لما أمعنوا في الكفر، هذا يقال له: القنوت في النوازل هذا مشروع.\nأما القنوت في الفجر دائماً فالصواب: أنه غير مشروع؛ لأن سعد الأشجعي سأل أباه فقال: يا أبت! صليت خلف رسول الله ﷺ وخلف أبي بكر و عمر و عثمان و علي أفكانوا يقنتون في الفجر؟ فقال أبوه: أي بني محدث وهو سعد بن طارق الأشجعي رواه الخمسة إلا أبا داود بإسناد جيد.\nفهذا يدل على أن القنوت في الفجر غير مشروع، إلا للنوازل خاصة كما تقدم، وأما رواية أنه كان يقنت في الصبح حتى ما زال في حياته عليه الصلاة والسلام، هذا ليس بصحيح بل هو ضعيف، في بعض الروايات عن أنس أنه كان يقنت حتى فارق الدنيا عليه الصلاة والسلام، ولكنه لو صح لكان واضحاً، لكنه حديث ضعيف الإسناد، وقال بعضهم: لو صح معناه أنه كان يطيل الوقفة بعد الركوع؛ لأن طول القيام يسمى: قنوت، وليس معناه القنوت المعروف، بل معناه أنه كان يطيل القيام بعد الركوع عليه الصلاة والسلام ويسمى قنوتاً، ولكن الحديث مثلما تقدم، ليس إسناده بصحيح ولا يعتمد عليه.\nفالصواب: أنه لا يشرع القنوت في الفجر على صفة دائمة، وإنما يشرع فيها إذا كان هناك نازلة بالمسلمين أو في المغرب أو في العشاء لا بأس أو في الظهر والعصر إذا كان هناك نازلة قنت فيما شاء من الصلوات الخمس، والأفضل في الفجر والمغرب. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8726/القنوت-في-الفجر-غير-مشروع-الا-للنوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_321/32106.mp3","categories":["القنوت في الصلاة"]},{"id":10725,"question":"من جمهورية مصر العربية المستمع حسن عاشور بعث برسالة ضمنها بعض الأسئلة يقول في أحدها: ما رأي الدين في سجدة السهو عند نسيان القنوت في صلاة الفجر، وهل القنوت مشروع أو لا جزاكم الله خيراً؟","title":"حكم القنوت في الفجر وسجود السهو عند نسيانه","answer":"الجواب: الصواب أن القنوت ليس مشروعاً في صلاة الفجر كل يوم، ولكن يشرع عند وجود النوازل، كأن ينزل بهم النازلة من حرب، فيقنت المسلمون في الفجر أو في غيرها يدعون الله كشفها والنصر على الأعداء، كما كان النبي يفعل عليه الصلاة والسلام، ويدعو للمجاهدين بالنصر، ويدعو على الكفار بالهزيمة، لا بأس، أما القنوت بصفة دائمة في الفجر أو في غيرها هذا لا أصل له، وإن ذهب إليه بعض أهل العلم، بعض العلماء ذهب إلى ذلك وقال: يستحب في الفجر خاصة؛ لأحاديث ضعيفة في ذلك، والصواب أنه لا يستحب في الفجر بصفة دائمة، وإنما يستحب للنوازل؛ لما ثبت في السنن بإسناد جيد، عن سعد بن طارق الأشجعي أنه قال لأبيه: يا أبتاه إنك أدركت رسول الله ﷺ وأبا بكر وعمر وعثمان وعليـاً أفكانوا يقنتون في الفجر؟ فقال طارق رحمه الله ورضي عنه: أي بني محدث، يعني: لم يكن يفعله النبي ﷺ ولا خلفاؤه الراشدون، فدل ذلك على أنه غير مشروع، يعني: بصفة دائمة.\nوإذا صليت مع قوم يقرءون القنوت فلا بأس، صل معهم واقنت معهم؛ لأن لهم شبهة، ولأنهم قالوا ذلك بسبب ما ورد في بعض الأحاديث التي ظنوها صحيحة، أو ظنوها دالة على ما ذهبوا إليه، فأنت معذور إذا صليت معهم، وهم معذورون إذا تلقوا ذلك عن غيرهم، معتقدين أنه مشروع، لكن من عرف العلم وعرف الحق يبينه للناس، ويوضحه للناس وأن هذا غير مشروع، وأن الصواب تركه إلا من علة، وهي وجود نازلة بالمسلمين، وعدو نزل بهم، فإذا قنتوا من أجل الدعاء للمسلمين، بالنصر على الأعداء، والدعاء على الأعداء بالهزيمة والخذلان هذا فعله الرسول ﷺ، وفعله أصحابه رضي الله عنهم وأرضاهم، أما لو تركه الإنسان ناسياً فلا يشرع له السجود، لأنه مستحب وليس بلازم، عند من قاله هو مستحب، فلا يشرع له سجود السهو لو ترك القنوت ناسياً، فإن سجدوا للسهو فلا حرج في ذلك ولا بأس، ولا يضر الصلاة، لكن عدم السجود أولى؛ لأنه ليس بمشروع، وعلى القول بشرعيته فهو مستحب فقط لا يجب بتركه سجود السهو، عند من قال بشرعيته، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8904/حكم-القنوت-في-الفجر-وسجود-السهو-عند-نسيانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34407.mp3","categories":["القنوت في الصلاة"]},{"id":10730,"question":"من جمهورية مصر العربية المستمع حسن عاشور بعث برسالة ضمنها بعض الأسئلة يقول في أحدها: ما رأي الدين في سجدة السهو عند نسيان القنوت في صلاة الفجر، وهل القنوت مشروع أو لا جزاكم الله خيراً؟","title":"حكم القنوت في الفجر وسجود السهو عند نسيانه","answer":"الجواب: الصواب أن القنوت ليس مشروعاً في صلاة الفجر كل يوم، ولكن يشرع عند وجود النوازل، كأن ينزل بهم النازلة من حرب، فيقنت المسلمون في الفجر أو في غيرها يدعون الله كشفها والنصر على الأعداء، كما كان النبي يفعل عليه الصلاة والسلام، ويدعو للمجاهدين بالنصر، ويدعو على الكفار بالهزيمة، لا بأس، أما القنوت بصفة دائمة في الفجر أو في غيرها هذا لا أصل له، وإن ذهب إليه بعض أهل العلم، بعض العلماء ذهب إلى ذلك وقال: يستحب في الفجر خاصة؛ لأحاديث ضعيفة في ذلك، والصواب أنه لا يستحب في الفجر بصفة دائمة، وإنما يستحب للنوازل؛ لما ثبت في السنن بإسناد جيد، عن سعد بن طارق الأشجعي أنه قال لأبيه: يا أبتاه إنك أدركت رسول الله ﷺ وأبا بكر وعمر وعثمان وعليـاً أفكانوا يقنتون في الفجر؟ فقال طارق رحمه الله ورضي عنه: أي بني محدث، يعني: لم يكن يفعله النبي ﷺ ولا خلفاؤه الراشدون، فدل ذلك على أنه غير مشروع، يعني: بصفة دائمة.\nوإذا صليت مع قوم يقرءون القنوت فلا بأس، صل معهم واقنت معهم؛ لأن لهم شبهة، ولأنهم قالوا ذلك بسبب ما ورد في بعض الأحاديث التي ظنوها صحيحة، أو ظنوها دالة على ما ذهبوا إليه، فأنت معذور إذا صليت معهم، وهم معذورون إذا تلقوا ذلك عن غيرهم، معتقدين أنه مشروع، لكن من عرف العلم وعرف الحق يبينه للناس، ويوضحه للناس وأن هذا غير مشروع، وأن الصواب تركه إلا من علة، وهي وجود نازلة بالمسلمين، وعدو نزل بهم، فإذا قنتوا من أجل الدعاء للمسلمين، بالنصر على الأعداء، والدعاء على الأعداء بالهزيمة والخذلان هذا فعله الرسول ﷺ، وفعله أصحابه رضي الله عنهم وأرضاهم، أما لو تركه الإنسان ناسياً فلا يشرع له السجود، لأنه مستحب وليس بلازم، عند من قاله هو مستحب، فلا يشرع له سجود السهو لو ترك القنوت ناسياً، فإن سجدوا للسهو فلا حرج في ذلك ولا بأس، ولا يضر الصلاة، لكن عدم السجود أولى؛ لأنه ليس بمشروع، وعلى القول بشرعيته فهو مستحب فقط لا يجب بتركه سجود السهو، عند من قال بشرعيته، نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8904/حكم-القنوت-في-الفجر-وسجود-السهو-عند-نسيانه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_344/34407.mp3","categories":["القنوت في الصلاة"]},{"id":11111,"question":"ما هي الحالات التي يجوز فيها دعاء القنوت؟ وما صيغته؟ وهل تجوز الزيادة عليه؟","title":"بيان متى يشرع القنوت وصيغته","answer":"الجواب: دعاء القنوت يشرع في الوتر كل ليلة، وقد جاء في حديث الحسن بن علي بيانه وهو: اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت، وتولنا فيمن توليت، وبارك لنا فيما أعطيت، وقنا شر ما قضيت، فإنك تقضي ولا يقضى عليك، وإنه لا يذل من واليت، ولا يعز من عاديت، تباركت ربنا وتعاليت  اللهم إني أعوذ برضاك من سخطك .. ... في حديث آخر حديث علي زيادة: اللهم إني أعوذ برضاك من سخطك وبعفوك من عقوبتك، وأعوذ بك منك لا أحصي ثناءً عليك أنت كما أثنيت على نفسك. وإذا دعا بزيادة فلا بأس، إن دعا بدعوات طيبة زيادة كله طيب، هذا قنوت الوتر يسمى قنوت الوتر، في الركعة الأخيرة الواحدة التي يوتر بها، بعدما يرفع من الركوع يرفع يديه ويقنت هذا القنوت، ويدعو بما يسر الله له من الدعاء. ويشرع القنوت أيضًا في النوازل، إذا نزل بالمسلمين نازلة، تعدى عليهم العدو، أو حصل عليهم شدائد، يدعون الله بتفريجها وإزالتها في جميع الصلوات، في الظهر والعصر والمغرب والعشاء والفجر أو في بعضها. وقد كان النبي في الغالب إذا نزل به أمر قنت في الفجر، وربما قنت في الفجر والمغرب جميعًا، وربما قنت في الصلوات الخمس كلها، وكان يقنت في المدينة يدعو على كفار قريش لما أخرجوه وآذوه، ويدعو للمستضعفين من المسلمين بمكة .... أن الله يخلصهم من شر عدوهم وينجيهم، ولما تعدى بعض الأعراب على جماعة من أصحابه قنت يدعو عليهم شهرًا -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، إذًا الزيادة في الدعاء الوارد للقنوت جائزة؟ الشيخ: لا حرج .. نعم، كان عمر يزيد في ذلك، نعم.  المقدم: بارك الله فيكم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9289/بيان-متى-يشرع-القنوت-وصيغته","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_368/36807.mp3","categories":["القنوت في الصلاة"]},{"id":11956,"question":"أحد الإخوة المستمعين بعث برسالة يقول: المرسل محمد نصر عبد زغلول، يسأل سماحتكم عددًا من الأسئلة من بينها سؤال يقول: علمت أن القنوت في الصلاة لا يكون إلا في النوازل فقط، وآمنت بذلك وصدقت، ولكن إذا كانت الجماعة تقنت في صلاة الفجر بالمسجد الذي أصلي فيه، فهل لي أن أخالفهم ولا أقنت معهم، أم أبقى معهم؟ جزاكم الله خيرًا.","title":"حكم الصلاة خلف من يقنت في الفجر دائمًا","answer":"الجواب:  لا مانع أن تبقى معهم، وتنصحهم؛ لأن بعض أهل العلم يرى القنوت في الفجر، ورد في هذا بعض الأحاديث التي احتج بها بعض أهل العلم، ولكنها ضعيفة، وإنما القنوت في الفجر حصره النبي ﷺ في النوازل وفي المغرب وفي العشاء وفي بقية الصلوات، في النوازل، عندما يقع حرب على المسلمين، أو شر عليهم، يدعو الله على من ظلم المسلمين، وتعدى عليهم، ويدعو الله للمسلمين المستضعفين بالنجاة من سبي أعدائهم، أما الاستمرار في القنوت في الفجر؛ فهذا خلاف الشرع، وهو الصواب تركه، لكن إذا كنت مع قوم يقنتون، وقد أفتاهم بعض أهل العلم بذلك؛ فاقنت معهم، وانصح الإمام أنت وإخوانك بترك ذلك، هذا هو المشروع لك، النصيحة أنت وإخوانك، وإرشاده إلى أهل العلم الذين يعلمونه أن القنوت في الفجر غير مشروع إلا في النوازل. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10141/حكم-الصلاة-خلف-من-يقنت-في-الفجر-داىما","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42820.mp3","categories":["صلاة الجماعة","القنوت في الصلاة"]},{"id":11957,"question":"إذا قنتنا في رباعية، ففي أي وقت يكون، وبعد أي ركوع؟","title":"موضع القنوت في الرباعية وغيرها","answer":"الجواب:  في الركوع الأخير من كل صلاة، في الركوع الأخير بعد الركوع، بعد الركوع في الركعة الأخيرة.","link":"https://binbaz.org.sa/fatwas/10142/موضع-القنوت-في-الرباعية-وغيرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_428/42821.mp3","categories":["القنوت في الصلاة"]},{"id":12039,"question":"هل القنوت بسبب النوازل يجوز في الظهر والعصر؟ وهل يكون جهرًا؟","title":"أوقات القنوت في النوازل","answer":"الجواب:  نعم القنوت في النوازل يجوز في جميع الأوقات الخمسة، قد قنت النبي ﷺ في الأوقات الخمسة في النوازل، والغالب أنه يقنت في الفجر والمغرب -عليه الصلاة والسلام- فإذا قنت في الفجر؛ كفى، أو في الفجر والمغرب؛ كفى، وإن قنت في الجميع؛ فلا بأس ﷺ على أحياء من العرب تعدوا على المسلمين، قنت عليهم شهرًا يدعو عليهم، ثم ترك، قد كان يقنت قبل الفتح، يدعو على أشخاص من أهل مكة، ويدعو للمستضعفين في مكة، عليه الصلاة والسلام.  فالقنوت في النوازل مشروع في جميع الأوقات، ولكن إذا خص من ذلك المغرب والفجر؛ فهذا هو الغالب من فعله -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10224/اوقات-القنوت-في-النوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_433/43308.mp3","categories":["القنوت في الصلاة"]},{"id":12195,"question":"أيضًا تقول: ما حكم رفع اليدين في دعاء القنوت؟","title":"حكم رفع اليدين في دعاء القنوت","answer":"الجواب:  مستحب في دعاء القنوت؛ لأنه ثبت أنه رفع في دعاء القنوت عند البيهقي -رحمه الله- نعم.","link":"https://binbaz.org.sa/fatwas/10381/حكم-رفع-اليدين-في-دعاء-القنوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_444/44402.mp3","categories":["القنوت في الصلاة"]},{"id":12207,"question":"أيضًا يسأل أخونا ويقول: ما حكم الإسلام في القنوت في صلاة الفجر؟ وهل تجوز الصلاة خلف الأئمة الذين يقنتون؟ وبم نرد على من يقول: إن ذلك هو مذهب الشافعي، حيث يتهموننا بأننا نبدع الشافعي؟","title":"قنوت الفجر وحكم الصلاة خلف الأئمة الذين يقنتون؟","answer":"الجواب:  الخلاف مشهور في القنوت، بعض أهل العلم رأى أنه يستحب في صلاة الفجر دائمًا، وبعض أهل العلم قال: لا يستحب إلا في النوازل، إذا حدث حادث، يعني قامت حرب ضد المسلمين؛ يقنت المسلمون في الصلاة، يدعون على العدو الذي حدث ضرره على المسلمين، كما قنت النبي في النوازل فإنه قنت ﷺ شهرًا يدعو على أحياء من العرب اعتدوا على بعض أصحابه -عليه الصلاة والسلام- فالقنوت في النوازل سنة مشهور معروف.  أما القنوت في الفجر دائمًا فالأفضل تركه؛ لأنه ثبت عن رسول الله ﷺ وعن الصديق وعمر وعثمان وعلي أنهم كانوا لا يقنتون في الفجر، قال سعد بن طارق الأشجعي قلت لأبي: يا أبت إنك صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي؛ أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث. فهذا يدل على أن السنة تركها إلا من حادث إذا في حادث من الحوادث فهذا يقنت في النوازل، أما الاستمرار؛ فالأفضل تركه، والأولى تركه لهذا الحديث الصحيح.  ومن قنت من الأئمة في الفجر كالشافعية وغيرهم ممن قنت في الفجر، فقد احتجوا بأحاديث وردت في ذلك أنه قنت في الصبح -عليه الصلاة والسلام- من حديث أنس، وأنه داوم على ذلك، ولكنها أحاديث ضعيفة التي فيها المداومة ضعيفة، وإنما قنت في النوازل في الفجر وغيره -عليه الصلاة والسلام- وهذا هو المعتمد والأفضل ألا يقنت في الفجر إلا في النوازل، وهكذا في المغرب والعشاء في النوازل، وفي الظهر والعصر في النوازل، أما الدوام على قنوت الفجر فالأولى تركه، الذي ينبغي تركه لحديث سعد بن طارق الذي سمعت. وإذا صليت مع أناس يقنتون؛ فلا حرج؛ لأنهم قد تبعوا بعض الأئمة، ولهم شبهة في بعض الأحاديث التي فيها ذكر القنوت، فالأمر في هذا واسع -إن شاء الله- إلا أن تركه هو الأولى، وهو الذي ينبغي؛ عملًا بالحديث الصحيح الذي سمعت وهو أنه محدث، يعني الاستمرار، أما فعله للنوازل؛ فلا بأس. المقدم: جزاكم الله خيرًا. أخونا يقول: إذا أنكرنا مثل ذلك يتهموننا بأننا نبدع الشافعي، ماذا نقول لهم؟ الشيخ: يعلمون أن هذا ليس تبديعًا للشافعي، ولكن من باب تحري الأرجح من الأقوال، من باب تحري الأرجح؛ لأن من قال: إنه بدعة احتج بحديث طارق بن أشيم الأشجعي، ومن زعم أنه سنة ومستحب احتج بأحاديث أخرى فيها ضعف، والأخذ بالشيء الثابت في الصحيح أولى وأحق عند أهل العلم، مع عدم التشنيع على من قنت، فإن هذه المسألة مسألة خفيفة، لا ينبغي فيها التشنيع والنزاع، وإنما يتحرى فيها الإنسان ما هو الأفضل والأقرب إلى السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10393/قنوت-الفجر-وحكم-الصلاة-خلف-الاىمة-الذين-يقنتون","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_445/44502.mp3","categories":["القنوت في الصلاة"]},{"id":12381,"question":"هل يلزم في صلاة الفجر دعاء القنوت؟","title":"هل يلزم دعاء القنوت في صلاة الفجر","answer":"الجواب:  دعاء القنوت ليس مشروعًا في صلاة الفجر، ولا غيرها، إنما المشروع في الوتر فقط، وهو ما يصليه الإنسان في الليل و... بعد صلاة العشاء، أو في آخر الليل يقنت في الركعة الأخيرة، إلا في النوافل إذا نزل بالمسلمين نازلة عدو؛ فإن الإمام والمسلمين يقنتون في الفجر، وفي غير الفجر بعد الركعة الأخيرة، بعد الركوع الأخير في الفجر والظهر والعصر والمغرب والعشاء، فعله النبي ﷺ لكن في النوازل إذا نزل بالمسلمين عدو، أو بطرف من أطرافهم، يقنتون، ويدعون الله على هذا العدو بالهزيمة، ويدعون الله للمسلمين بالنصر، كما فعله النبي -عليه الصلاة والسلام- نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم، فيما إذا كنت أقيم مع قوم لا يقنتون، ثم انتقلت إقامتي مع قوم يقنتون هل أقنت معهم، أو كيف تنصحونني؟ الشيخ: نعم إذا قنتوا؛ فاقنت معهم، وبين لهم السنة إذا كنت ذا علم، ... قوله ﷺ: إنما جعل الإمام ليؤتم به؛ فلا تختلفوا عليه ولهم شبهة؛ لأنه قاله بعض أهل العلم: قال بالقنوت في الفجر بعض أهل العلم دائمًا، فإذا قنتوا؛ فاقنت معهم، وعلمهم السنة إن كنت تعلم .. لعلهم يستفيدون منك. المقدم: بارك الله فيكم، إذًا القنوت في الفجر لا يوجب الخلاف بين المسلمين؟  الشيخ: لا ما ينبغي الخلاف بين المسلمين؛ لأن فيه شبهة وقال به بعض أهل العلم، لكن تركه هو السنة، هو الأفضل، هو الأحوط، هو الراجح؛ لقول سعد بن طارق الأشجعي : \"قلت لأبي : يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر، وخلف عمر، وخلف عثمان، وخلف علي أفكانوا يقنتون في الفجر؟ فقال طارق: أي بني محدث\".  فدل على أنه ليس من سنتهم القنوت في الفجر دائمًا، إنما هذا عند الحاجة، إذا نزل بالمسلمين نازلة عدو؛ يقنت في النوازل، في الفجر، وفي غيرها، هكذا فعل النبي ﷺ. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10593/هل-يلزم-دعاء-القنوت-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_401/40112.mp3","categories":["القنوت في الصلاة"]},{"id":12468,"question":"مستمع يقول: المستمع (ص. ع) أبو أنس يسأل سؤالين: في سؤاله الأول يقول: إذا قمت الليل، ووصلت إلى الوتر، هل يجوز أن أستمع إلى القنوت المسجل على أحد الأشرطة لأحد الأئمة، وأؤمن عليه وأنا في أثناء تأدية الوتر؟ وجهوني جزاكم الله خيرًا.","title":"حكم الاستماع إلى القنوت من الشريط المسجل أثناء صلاة الوتر","answer":"الجواب:  السنة لك أن تقنت أنت، ولا تسمع الشريط، تقنت أنت إذا يسر الله الدعاء بما تيسر من الدعوات، ولو قليلة يكفي والحمد لله، والقنوت ليس بلازم، لو أوترت بدون قنوت؛ لا بأس، وإن قنت بكلمات قليلة: اللهم اهدني فيمن هديت، وعافني فيمن عافيت، وتولني فيمن توليت، وبارك لي فيما أعطيت، وقني شر ما قضيت، فإنك تقضي، ولا يقضى عليك، وإنه لا يذل من واليت، ولا يعز من عاديت، تباركت ربنا وتعاليت كفى.  وإن زدت: اللهم إني أعوذ برضاك من سخطك، وبمعافاتك من عقوبتك، وأعوذ بك منك لا أحصي ثناء عليك، أنت كما أثنيت على نفسك أو زدت غير ذلك؛ فلا بأس مما يقنت به إخوانك المسلمون. المقصود: إذا دعوت بدعوات طيبة في القنوت مختصرة؛ كفى. المقدم: أما أن يعتمد على شريط مسجل، ويستمع إليه؟ الشيخ: ... ما ينبغي هذا. المقدم: لا ينبغي. الشيخ: نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10663/حكم-الاستماع-الى-القنوت-من-الشريط-المسجل-اثناء-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_404/40404.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":12672,"question":"مع مطلع هذه الحلقة نستعرض رسالة وصلت إلى البرنامج من المستمع محمد فرحان من اليمن، الأخ محمد يسأل في سؤاله الأول عن القنوت في صلاة الفجر، فيقول: حدثونا عن القنوت في صلاة الفجر، وعن حكمه، وعن حكم تركه، وهل كان الرسول ﷺ يقنت في صلاة الفجر؟ جزاكم الله خيرًا.","title":"هل كان يقنت رسول الله في صلاة الفجر؟","answer":"الجواب:  بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالقنوت في صلاة الفجر لم يثبت فيه حديث عن النبي -عليه الصلاة والسلام- جاءت فيه أحاديث ضعيفة، والصحيح: أنه كان يقنت في الحوادث، إذا نزل بالمسلمين نازلة؛ قنت في الفجر، وفي المغرب، وفي غيرهما، ويسمى قنوت النوازل، أما القنوت بصفة دائمة فلم يثبت عنه -عليه الصلاة والسلام- نعم جاء ذلك في بعض الأحاديث التي ... فيها ضعف، وثبت عن سعد بن طارق بن أشيم أنه قال لأبيه: يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي، أفكانوا يقنتون في الفجر؟ فقال: \"أي بني محدث\".  هذا يدل على أنهم ما كانوا يقنتون في الفجر إلا لعارض يعني: في النوازل لما ينزل بالمسلمين، فيقنتون عند النازلة دعاءً على العدو بالهزيمة، ودعاءً للمسلمين بالنصر، إذا هجم العدو على بلاد المسلمين، أو حصل بين المسلمين قتال مع عدوهم؛ قنت المسلمون، يدعون للمجاهدين بالنصر، وللأعداء بالهزيمة. أما استمرار بعض الناس على القنوت في الفجر فهو قول ضعيف مرجوح، وإن كان قال به جماعة من أهل العلم، لكن الأفضل والأولى تركه، لعدم الدليل الثابت عليه إلا إذا نزل بالمسلمين نازلة، هذا هو الأرجح، وإذا صليت مع من يقنت صل معهم والحمد لله؛ لأن لهم شبهة، وقال به بعض أهل العلم، وفيه بعض الأحاديث التي فيها ضعف، لكن الأولى والذي ننصح به إخواننا الترك، إلا إذا وجد ما يوجب ما يقتضى ذلك، مثل النوازل، مثلما قنت المسلمون للمجاهدين الأفغان لقتالهم مع عدوهم، والمسلمون في البوسنة والهرسك، وأشباه ذلك، هذا قنوت للنوازل، في الفجر وغيرها، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10882/هل-كان-يقنت-رسول-الله-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_417/41701.mp3","categories":["القنوت في الصلاة"]},{"id":12723,"question":"هل دعاء القنوت بعد الركعة الأخيرة، أم قبلها؟","title":"تحديد موضع القنوت في الصلاة","answer":"الجواب:  السنة في الركعة الأخيرة بعد الركوع، دعاء القنوت يكون في الركعة الأخيرة بعد الركوع. نعم.","link":"https://binbaz.org.sa/fatwas/10936/تحديد-موضع-القنوت-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_460/46011.mp3","categories":["القنوت في الصلاة"]},{"id":12840,"question":"يسأل عن القنوت في صلاة الفجر، هل هو صحيح، أو لا؟","title":"هل يصح القنوت في صلاة الفجر؟","answer":"الجواب:  الصواب أنه لا يشرع في صلاة الفجر، وأنه يفعل للنوازل، إذا نزل بالمسلمين نازلة يقنت بعد الفجر، بعد الركوع في الركعة الأخيرة من صلاة الفجر، مثل: الدعاء على الكفار في بلاد أفغانستان، الدعاء على الكفار في فلسطين، على الكفار في الفلبين؛ لأنهم... ظلموا المسلمين، وقتلوا المسلمين، وأشباه ذلك، كان النبي ﷺ يقنت في الفجر، وفي غيرها عند النوازل، عندما يوجد من الكفار أذى للمسلمين، أو قتال للمسلمين، يدعو عليهم بعد الركوع، يدعو عليهم ويقول: اللهم قاتل الكفرة والمشركين، اللهم زلزلهم، اللهم انصرنا عليهم، وما أشبه ذلك. أما ما يفعله بعض الناس من القنوت دائمًا في الفجر هذا... غير مستحب، بل الذي ينبغي تركه، ثبت في السنن عن سعد بن طارق الأشجعي  أنه قال لأبيه: \"يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر، وخلف عمر، وخلف عثمان، وخلف علي -رضي الله عنهم- أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث. فهذا يدل على أنه محدث، وأن السنة تركه، وإن ذهب إليه بعض العلماء، بعض أهل العلم ذهبوا إلى فعله، واستدلوا بأحاديث ضعيفة في ذلك، والصواب أنه لا يفعل، وأن السنة تركه، هذا هو الصواب، وهذا هو السنة، وهذا هو الراجح من قولي العلماء، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11054/هل-يصح-القنوت-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_464/46406.mp3","categories":["القنوت في الصلاة"]},{"id":13046,"question":"السائلة: ... أيمن محمد جمهورية مصر العربية دمياط لها هذا السؤال تقول: هل قنت الرسول ﷺ في صلاة الصبح في الركعة الأخيرة بعد الركوع رافعًا يديه يقول: اللهم اهدنا فيمن هديت كل ليلة حتى فارق الدنيا؟ وما معنى دعاء القنوت: اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت؟ جزاكم الله خيرًا.","title":"هل قنت الرسول ﷺ في صلاة الصبح؟","answer":"الجواب:  لم يثبت عن النبي ﷺ أنه كان يقنت في الفجر، لا بقوله اللهم اهدنا فيمن هديت ولا بغيره، إنما كان يقنت عند النوازل، إذا نزل بالمسلمين نازلة من تسليط عدو، أو نحو ذلك؛ قنت يدعو على العدو في الفجر، وفي غير الفجر. أما ما اعتاده بعض الناس من القنوت دائمًا في الفجر: اللهم اهدنا هذا خلاف المشروع، والذي ينبغي تركه؛ لأن الأحاديث التي في هذا ضعيفة، وإنما المشروع القنوت عند النوازل، عند وجود التعدي من الأعداء الكفار على المسلمين، يقنت المسلمون، يدعون عليهم في الفجر والمغرب والعشاء والظهر والعصر، لكن الفجر كان قنوته فيه أكثر، يدعو على المشركين، أما دائمًا فليس له أصل، والأحاديث في هذا ضعيفة، والذي ينبغي ترك ذلك، نعم.","link":"https://binbaz.org.sa/fatwas/11263/هل-قنت-الرسول-ﷺ-في-صلاة-الصبح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_505/50506.mp3","categories":["القنوت في الصلاة"]},{"id":13560,"question":"أخونا يقول في سؤال آخر: إمامنا يدعو بالقنوت أحيانًا في صلاة الفجر والمغرب والعشاء، وذلك بعد الرفع من الركوع الأخير، لكن يا سماحة الشيخ! بعد القنوت يدعو أيضًا بدعاء شتى، ويرفع يديه، فهل هذا الدعاء بعد القنوت جائز؟ وهل نرفع أيدينا معه، أم نكتفي بالتأمين؟","title":"حكم القنوت ورفع اليدين في الصلوات المكتوبة","answer":"الجواب: القنوت مشروع في النوازل، في الدعاء للمجاهدين، والدعاء على الكافرين، فإذا قنت من أجل النوازل في بعض الأحيان كحال المجاهدين الأفغان، وحال المجاهدين في فلسطين، وغيرهم، يدعو لهم بالنصر، ويدعو على الكفار بالخذلان، فهذا مشروع، ويرفع يديه، وأنتم ترفعون أيديكم وتؤمنون، كما في الاستسقاء يرفع يديه في الاستسقاء، طلب الغوث، ويرفع الناس أيديهم ويؤمنون. أما القنوت لغير ذلك؛ فلا يستحب له الوتر، إذا أوتر في الليل قنت بعد الركوع في الركعة الأخيرة. أما ما يفعله بعض الناس من القنوت في الصبح دائمًا؛ فهذا لا ينبغي، بل الذي ينبغي تركه؛ لأن الرسول ﷺ ما كان يفعل القنوت إلا في النوازل، يعني: إذا نزلت بالمسلمين نازلة؛ دعا للمسلمين، ودعا على الكافرين أوقاتًا معينة، ثم يترك عليه الصلاة والسلام، فأما القنوت في الصبح بصفة دائمة؛ فهذا الصحيح من أقوال العلماء أنه غير مشروع. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11882/حكم-القنوت-ورفع-اليدين-في-الصلوات-المكتوبة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_480/48006.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":13612,"question":"يقول هذا السائل: في صلاة الفجر، وفي الركعة الأخيرة يقوم الإمام برفع يديه، والدعاء، والذين وراءه يقولون: آمين، يؤمنون على ذلك، ما رأيكم في هذا سماحة الشيخ عبدالعزيز ؟","title":"ما حكم الدعاء في الركعة الثانية من صلاة الفجر؟","answer":"الجواب: السنة عدم القنوت في الفجر إلا في النوازل، إذا نزل بهم نازلة مثل جدب، واستغاثوا، أو دعاء على العدو؛ لا بأس، عدو نزل بالمسلمين، أما كونه يتخذ القنوت عادة في الفجر؛ فالصواب أنه لا يشرع، وما كان النبي ﷺ يفعل ذلك إلا عند الحاجة. لكن لو صليت مع إنسان يقنتون؛ فلا بأس أن تؤمن معهم؛ لأن لهم شبهة، المسألة فيها خلاف بين العلماء، فإذا صليت مع جماعة يقنتون في الفجر؛ فلا بأس أن تصلي معهم، ولا بأس أن تؤمن على الدعاء معهم؛ لأن لهم شبهة في ذلك، ولأن بعض أهل العلم رأى ذلك.نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11952/ما-حكم-الدعاء-في-الركعة-الثانية-من-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_528/52806.mp3","categories":["القنوت في الصلاة"]},{"id":13785,"question":"أعرض عليكم عملي هذا وأرجو أن توجهوني: إنني أصلي العشاء ثم أصلي بعده ركعتين، ثم أصلي ركعتين بتسليمة واحدة، ثم أصلي ركعة وأرفع يدي وأدعو بصوت مرتفع قليلًا، هل ما أفعله صحيح؟","title":"حكم رفع المرأة صوتها في دعاء الوتر","answer":"","link":"https://binbaz.org.sa/fatwas/12139/حكم-رفع-المراة-صوتها-في-دعاء-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48122.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":13852,"question":"في ثاني أسئلة هذا السائل يقول: ما حكم القنوت في صلاة الوتر؟ وهل يجب علي شيء إذا تركته؟","title":"حكم القنوت في الوتر وهل على من تركه شيء؟","answer":"الجواب:","link":"https://binbaz.org.sa/fatwas/12229/حكم-القنوت-في-الوتر-وهل-على-من-تركه-شيء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_537/53724.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":14109,"question":"من جمهورية اليمن الديمقراطية الشعبية حضرموت رسالة بعث بها مستمع من هناك هو محمد أبو بكر أحمد، الأخ محمد يسأل ويقول: هل يجوز القنوت في صلاة الفجر، مع الدليل من الحديث؟ جزاكم الله خيرًا.","title":"هل يجوز القنوت في صلاة الفجر؟ وما الدليل؟","answer":"الجواب: يشرع القنوت في صلاة الفجر للدعاء للمجاهدين ونصر دين الله  والسلامة من شر مكائد الأعداء بصفة مؤقتة لا مستمرة، كما فعل النبي ﷺ، فإنه كان ربما قنت يدعو لقوم أو على قوم، قالوا: وقنت يدعو على قبائل من العرب شهرًا عليه الصلاة والسلام، فإذا قنت المسلم من أجل حدوث أمر يضر المسلمين يدعو الله أن يكشفه، أو من أجل الدعوة للمجاهدين كالمجاهدين الأفغان أو نحو ذلك فهذا أصله مشروع لكن يكون مؤقتًا كما فعله النبي ﷺ.\nأما ما يفعله بعض الناس من استمرار في القنوت لصلاة الفجر فهذا غير مشروع على الصحيح، لما ثبت من حديث سعد بن طارق بن أشيم قال: «قلت لأبي: يا أبت إنك صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي، أفكانوا يقنتون في الفجر؟ فقال: أي بني! محدث» هكذا رواه الإمام أحمد والترمذي والنسائي وهو إسناد صحيح، وهذا يدل على أنه ليس من عادة ﷺ ولا من عادة الخلفاء الراشدين القنوت بصفة مستمرة في الفجر، وإنما يقنت لعارض وحادث يضر المسلمين أو للدعاء لقوم بالنصر على الأعداء ونحو ذلك، فالدعاء لقوم بالنصر على الأعداء أو الدعاء على الأعداء بالهزيمة ونحو ذلك كل هذا لا بأس به بصفة مؤقتة كما فعله النبي عليه الصلاة والسلام. نعم.\nالمقدم: جزاكم الله خيرًا. سماحة الشيخ!","link":"https://binbaz.org.sa/fatwas/12556/هل-يجوز-القنوت-في-صلاة-الفجر-وما-الدليل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_614/61415.mp3","categories":["القنوت في الصلاة"]},{"id":14128,"question":"هل للقنوت في الوتر على الطريقة المعروفة أصل؟ وما هو الدليل؟","title":"ما دليل القنوت في الوتر؟","answer":"الجواب: نعم، القنوت سنة في الوتر من الليل، علمه النبي ﷺ الحسن بن علي، وتعليم النبي ﷺ لشخص من الصحابة تعليم الأمة كلها عليه الصلاة والسلام، فالقنوت سنة، فينبغي للمؤمن إذا صلى الركعة الأخيرة الواحدة إذا رفع رأسه من الركوع أن يرفع يديه ويقنت، يدعو: اللهم اهدني فيمن هديت.. وما تيسر معه من الدعاء، ثم يسجد كما فعله النبي ﷺ وكما فعله الصحابة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12573/ما-دليل-القنوت-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_615/61509.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":14359,"question":"يقول: هل هناك من دعاء ندعو به بعد القيام من الركوع في الركعة الثانية من صلاة الفجر؟ وما هو القنوت؟","title":"معنى القنوت وحكمه في صلاة الفجر","answer":"الجواب: القنوت معروف، هو قنوت الوتر، وقنوت النوازل، وقنوت الصلوات الخمس، فالسنة ألا يقنت إلا في الوتر، هذا السنة، وهو الركعة الأخيرة من الوتر في الليل، وفي النهار، ما في قنوت إذا صلى يصلي شفعًا، إذا فاته الليل صلى من النهار شفعًا، إذا كان عادته في الليل ثلاث صلى أربعًا في النهار تسليمتين، وإذا كان عادته في الليل خمسًا، وفاته بالنوم أو بالمرض صلى من النهار ست ركعات، ثلاث تسليمات، وهكذا، ليس بقنوت، القنوت في الليل في الركعة الأخيرة، وقد علمه النبي ﷺ الحسن بن علي . وذهب بعض أهل العلم إلى أنه يقنت في الصبح دائمًا، وهذا قول ضعيف، الصواب: أنه لا يقنت في الأوقات كلها إلا في النوازل، إذا حدث نازلة للمسلمين، مثل نازلة اجتياح الكويت من حكومة العراق، هذه نازلة يقنت فيها المسلمون في الفجر وغيره، ويدعون الله على من ظلم، ويدعون الله لمن ظلم بالنصر والتأييد، وأن يردهم إلى بلادهم، يدعون الله على من تعدى على المسلمين وآذاهم، هذا يسمى القنوت في النوازل، فعله النبي ﷺ، فعله في الفجر وغيره، إذا قنت الإمام في الفجر، أو في المغرب، أو في العشاء، أو في الظهر، أو في العصر، أو في الجميع، يدعو على الظالم، وعلى من ظلم المسلمين، وتعدى عليهم، فلا بأس به، بل هو مشروع، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12839/معنى-القنوت-وحكمه-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_487/48706.mp3","categories":["القنوت في الصلاة"]},{"id":14547,"question":"نفس السؤال تقريبًا إنما عن القنوت في الوتر؟","title":"هل القنوت في الوتر سنة؟","answer":"الجواب: سنة أيضًا القنوت، من فعله فهو أفضل، ومن ترك فلا حرج، نعم. المقدم: جزاكم الله خيرًا، إذًا من جاء بدعاء الاستفتاح وجاء بالقنوت في الوتر فثوابه أكثر؟ الشيخ: فهو السنة، فهو السنة. المقدم: فهو سنة. الشيخ: ومن ترك فلا حرج عليه. المقدم: ولكن الثواب لمن جاء؟ الشيخ: أي نعم، من فعل السنة له ثوابها، ومن ترك فلا حرج عليه، مثل صلاة الراتبة للظهر، صلاة الراتبة للمغرب، صلاة العشاء، صلاة راتبة الفجر، الرواتب صلاة الضحى، من أتى بها حصل أجرها، ومن تركها فاته أجرها، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13044/هل-القنوت-في-الوتر-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_489/48905.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":14568,"question":"يقول هذا السائل في سؤاله: ما هو حكم دعاء القنوت؟ وهل يجب أن يواظب عليه في صلاة الوتر أم لا وكذلك حكمه في صلاة الفجر؟","title":"ما حكم دعاء القنوت؟ وهل يجب أن يواظب عليه؟","answer":"الجواب: القنوت مستحب في صلاة الوتر، وليس بواجب، قد صح عن رسول الله ﷺ أنه قال للحسن بن علي أن يقنت في وتره بقوله: اللهم اهدنا فيمن هديت إلى آخره. فالقنوت مستحب وليس بواجب، فلو أوتر ولم يقنت فلا شيء عليه، أما القنوت في الفجر فلا يستحب، وليس بمشروع إلا إذا كان للنوازل؛ لما ثبت عن سعد بن طارق بن أشيم الأشجعي أنه قال لأبيه: «يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي أفكانوا يقنتون في الفجر؟ فقال: أي بني، محدث» يعني: ثبت عنه ﷺ أنه قنت في النوازل في الفجر وفي غيرها إذا نزل بالمسلمين نازلة عدو قنت يدعو على العدو بعد الركوع في الركعة الأخيرة في الفجر وغيرها، فيدعو على المشركين إذا آذوا المسلمين قتلوهم أو قاتلوهم دعا على جماعة كثيرة من أهل الشرك وقنت على قوم شهرًا يدعو عليهم. فالقنوت في النوازل أمر مشروع ضد الكفار المعتدين، أما أن يقنت في الفجر من دون حاجة من دون وجود نوازل لا فلا يشرع هذا، نعم، هذا هو الصحيح. المقدم: قد يشكل على البعض من المستمعين كلمة النوازل يا سماحة الشيخ؟ الجواب: النوازل هي ما ينزل بالمسلمين من العدو، كعدو يحاصر بلد المسلمين أو يقاتلهم، فهذا يدعى عليه في الصلوات في الركعة الأخيرة بعد الركوع يدعو عليه ولي الأمر، ويدعى عليه في المساجد في الركعة الأخيرة بعد الركوع، يرفع الإمام يديه والمأمومون يدعون: اللهم اقتلهم، اللهم اقتلهم، اللهم اكفينا شرهم، اللهم عليك بهم فإنهم لا يعجزونك، بالدعوات التي مضمونها الدعاء عليهم بالهزيمة والنصر للمسلمين، والهزيمة للكافرين، نعم.","link":"https://binbaz.org.sa/fatwas/13065/ما-حكم-دعاء-القنوت-وهل-يجب-ان-يواظب-عليه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_556/55606.mp3","categories":["القنوت في الصلاة"]},{"id":15030,"question":"أيضًا يقول المستمع (م. م. ع) من مكة المكرمة: عند الإمام مالك: القنوت في صلاة الصبح في الركعة الثانية، وعند الإمام أحمد بن حنبل: القنوت في صلاة العشاء في الوتر، فما دليل كل واحد منهم؟وشكرًا.","title":"حكم القنوت في الوتر وفي الفجر","answer":"الجواب: القنوت مشروع في الليل، وليس في العشاء، بل بعد العشاء إلى آخر الليل، هذا مشروع عند الجميع، القنوت في الليل مشروع عند جميع أهل العلم، سنة، الوتر بين صلاة العشاء إلى طلوع الفجر، ويشرع فيه القنوت؛ لحديث الحسن بن علي قال: علمني الرسول كلمات أقولهن في قنوت الوتر: اللهم اهدني فيمن هديت، وعافني فيمن عافيت.. الحديث، فهذا المشروع، الوتر عند الجميع. أما القنوت: فلست أدري عنه الآن هو محل إجماع، أو محل خلاف، لكنه سنة بلا شك، وإن لم يكن فيه إجماع، وهو سنة لحديث الحسن ، في قنوت الوتر في الليل. أما القنوت الذي يفعله بعض أهل العلم في الصباح: كالشافعية والمالكية، فهو -على الصحيح- غير مشروع، إلا في النوازل، إذا حدث نازلة بـالمسلمين، مثل عدو أحاط بالبلد، أو ببلد من بلدان المسلمين، يقنتوا في الفجر، وفي غير الفجر، للدعاء عليه. أما القنوت الدائم في الفجر، فهذا غير مشروع على الصحيح، وقد احتج من قال بـشرعيته، بحديث جاء عن أنس  أنه قال: \"فأما في الصبح فلم يزل يقنت حتى فارق الدنيا\" لكنه حديث ضعيف، وجاءت الأحاديث تفسره بأنه لم يزل يقنت، يعني: في النوازل خاصة. وأما من قال: إنه لا يشرع في الصبح، فحجته أظهر، وهو ما رواه أحمد وأبو داود والنسائي، وغيرهم عن النبي ﷺ عن سعد بن طارق قال: \"قلت لأبي طارق بن أشيم: يا أبتاه إنك صليت خلف رسول الله ﷺ، وخلف أبي بكر، وعمر، وعثمان، وعلي، أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث\" فهذا الحديث يدل على أنه محدث، وأنه لا ينبغي في الصبح إلا في النوازل، أما كونه يفعل دائمًا، فالصواب أنه محدث، ولا يشرع. والذين قالوا بشرعيته، لعله خفي عليهم هذا الحديث، ما بلغهم هذا الحديث، حديث سعد بن طارق، ولو بلغهم لقالوا به، لكن لعله لم يبلغهم، أو بلغهم وتأولوه على غير ظاهره. فالحاصل: أن الصواب والأرجح: أن القنوت يكون في الوتر في الليل، وفي النوازل أيضًا في الفجر وغيرها النوازل، أما الاستمرار على القنوت في صلاة الفجر دائمًا، فهذا الصواب تركه، وأنه ليس بمشروع لحديث طارق بن أشيم، هذا الذي سمعته، والعبادات توقيفية، لا يجوز منها إلا ما قام عليه الدليل، ولكن لو صلى الإنسان خلف واحدٍ من هؤلاء فلا بأس، يتابعه في ذلك؛ لأنه له شبهة في هذا الشيء، فلا حرج إذا صلى مع واحد يقنت في الفجر، وتابعه لا حرج في ذلك، لكن ينصح من يفعل ذلك، ينصح بأن الأفضل والأولى والأرجح ترك ذلك؛ لأن طارقًا ذكر أن هذا محدث، وأنه ليس من عادة النبي ﷺ، ولا عادة أصحابه خلفائه الراشدين، وما كان كذلك؛ فالواجب تركه، إلا إذا وجد سبب لذلك، من جنس ما تقدم، كجنس النوازل، نعم.","link":"https://binbaz.org.sa/fatwas/13537/حكم-القنوت-في-الوتر-وفي-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65309.mp3","categories":["القنوت في الصلاة"]},{"id":15478,"question":"هذه رسالة من المستمع: محجوب علي حسن من الرياض، يقول: نحن جماعة من رعايا الدول العربية نعمل بالمملكة، ولنا مسجد بمحل عملنا، نؤدي به جميع الصلوات، ولكن إمامنا له عادة بعد الركعة الثانية من صلاة الفجر دائمًا، يرفع يديه بالدعاء لمدة طويلة، ويرفع المأمومون أيديهم أيضًا خلفه، وبعد الدعاء يسجد ليكمل الصلاة، ولما كان أكثر المصلين يتجادلون في هذا الموضوع، وأكثرهم يعتبره غير صحيح ولا يجوز؛ لأنهم لم يفعلوا ذلك في الحرمين، وهما مقياس وقدوة، وعندما أخبرنا الإمام بذلك أخبرنا بأن ذلك لا يعتبر دليلًا، فنرجو توضيح الحقيقة، ولا زالت الشكوك بين المصلين حول هذا الموضوع، وإمامنا يقول لنا حينما قلنا له ذلك قال: إن المذاهب متعددة، فهي تصل إلى ألف وستمائة مذهب في الإسلام، فما رأيكم في هذا الموضوع؟أثابكم الله.","title":"حكم القنوت في الفجر وعدد المذاهب المعتبرة","answer":"الجواب: لا ريب أن ما فعله الإمام قد قال به بعض أهل العلم، ويسمى القنوت، وهو الدعاء الذي يؤتى به بعد الركوع في الركعة الثانية من الفجر، هذا ذهب إليه بعض أهل العلم، كـالشافعية -رحمة الله عليهم-، وهو قول معروف في الإسلام، ويحتجون ببعض الأحاديث الواردة في ذلك عن النبي ﷺ: \"أنه كان يقنت حتى فارق الدنيا في الصبح\". ولكن الصواب من الأقوال في هذا: أنه لا يشرع إلا للنوازل، إذا نزل بالمسلمين نازلة من عدو نزل بهم، فإنه لا بأس أن يقنتوا، بل يشرع لهم القنوت، مدة معينة، ثم يتركون القنوت؛ لأنه ﷺ كان يقنت في النوازل وقتًا معينًا، ثم يترك ذلك -عليه الصلاة والسلام-، قال أنس : \"كان النبي ﷺ لا يقنت إلا إذا دعا لقوم أو على قوم\"، \"وقنت شهرًا ﷺ يدعو على أحياء من العرب، ثم ترك ذلك -عليه الصلاة والسلام-\". أما الحديث: \"أنه كان يقنت في الصبح حتى فارق الدنيا\" فهو ضعيف كما بيَّن أهل العلم. وقد ثبت في الحديث الآخر من حديث سعد بن طارق بن أشيم الأشجعي أنه قال لأبيه: «يا أبت، إنك صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي؛ أفكانوا يقنتون في الفجر؟ فقال له أبوه: أي بني محدث».\nفبين طارق -رحمه الله- وهو صحابي جليل أن قنوت الفجر محدث، وأنه لا ينبغي فعله، وهذا هو الأرجح، أرجح القولين، فينبغي للمؤمن أن يتحرى في صلواته، وفي سائر أعماله، ما يوافق السنة والكتاب العزيز، وأقوال أهل العلم المعتبرين، وهذا القول هو الأرجح أنه لا ينبغي القنوت. إلا إذا دعا لقوم أو على قوم في النوازل، مثل إذا قنت يدعو للمجاهدين في الأفغان، وعلى أعدائهم بعض الوقت ثم يترك. أما يستمر في القنوت بعد الركوع في الركعة الثانية من الفجر دائمًا هذا الصواب أنه غير مشروع، وإن قال به من قال به من الشافعية وغيرهم، فالصواب: أنه غير مشروع، وقد قال الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا[النساء:59] وإذا رددنا هذا الأمر إلى السنة وجدنا فيها الدلالة على أن هذا غير مشروع. فينبغي للإمام ترك ذلك، وعدم فعله عملًا بالسنة الصحيحة، واتباعًا لبقية أهل العلم في هذا الباب، ولا سيما في هذه البلاد، فإن هذه البلاد أئمتها لا يقنتون في الفجر أخذًا بالسنة الصحيحة التي بينا لك أيها السائل. وأما قول الإمام أن في الإسلام ألف وستمائة مذهب هذا كلام فيه مجازفة، وكلام لا ينبغي، فإن ليس كل مذهب يوجد يعتبر في الإسلام، هناك مذاهب باطلة، وهذه مبالغة قبيحة، لا ينبغي للإمام أن يقول مثل هذا، فليس كل مذهب يدعي صاحبه أنه مذهب إسلامي يقبل، المذاهب التي لا توافق الكتاب والسنة لا تعتبر. والمذاهب المشهورة أربعة: الشافعية، والحنفية، والمالكية، والحنبلية، وهم أئمة وعلماء كبار، اشتهرت مذاهبهم وانتسب إليهم علماء، فاشتهروا بذلك، ويلحق بهم أيضًا مذهب الظاهرية معروف، هذه مذاهب معروفة، وما اختلفوا فيه من المسائل يعرض على الكتاب والسنة، كل واحد قد يخطي، قد يغلط في بعض المسائل، فما اختلفوا فيه -رحمة الله عليهم- يعرض على الكتاب والسنة، فما وافق القرآن أو السنة الصحيحة وجب الأخذ به، وترك ما خالفه، سواء كان وافق مذهب مالك، أو مذهب أبي حنيفة أو الشافعي أو أحمد أو الظاهرية، هذا هو الصواب. أما المذاهب الأخرى التي يشير إليها هذا الإمام، هذه لا يعول عليها، ولا يلتفت إليها، بل ينبغي للمؤمن ألا يلتفت إلى غير هذه المذاهب، وهذه المذاهب هي المذاهب المعروفة عند أهل السنة، والمعروفة بالاستقامة، وتحري الحق، وعدم الزيغ والبدعة، أما المذاهب الأخرى فعند أهلها من البدع وعندهم من الانحراف ما يوجب التوقف عن الأخذ بمذاهبهم، وعدم النظر فيها؛ خوفًا من شرها وبدعتها، ولكن هذه المذاهب الخمسة المعروفة الظاهرية والمذاهب الأربعة هذه تعتني بالسنة والكتاب، وتعتني بأقوال الصحابة  وأرضاهم، وليس عندهم البدع التي عند غيرهم، فلهذا اقتنع بها أهل العلم، ورأوها مذاهب إسلامية معتبرة، ولكن ما اختلفوا فيه من ذلك يرجع فيه إلى الكتاب والسنة، ويعرض على كلام الله، وكلام رسوله ﷺ، فما وافقهما أو أحدهما وجب الأخذ به، وترك ما خالفه. وإذا عرضنا القنوت في الفجر دائمًا على الكتاب والسنة، لم نجد فيهما ما يدل على شرعيته، بل ما يدل  فيهما هو ما جاء في حديث طارق بن أشيم، ما يدل على أنه لا يشرع هذا القنوت بصفة دائمة، وإنما يشرع عند النوازل في الدعاء على أعداء الله، وفي الدعاء للمجاهدين في سبيل الله بالنصر في وقت معين، وقت الحاجة، ثم يوقف ويمسك، ولا يستمر، رزق الله الجميع التوفيق والهداية، نعم. المقدم: آمين، يا رب العالمين، جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/14014/حكم-القنوت-في-الفجر-وعدد-المذاهب-المعتبرة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_689/nour_68904.mp3","categories":["القنوت في الصلاة"]},{"id":15591,"question":"يقول السائل: في بعض الأحيان أنسى قراءة دعاء القنوت في صلاة الوتر، فهل أكمل الصلاة أم أصليها مرة أخرى؟","title":"حكم نسيان القنوت في صلاة الوتر","answer":"الجواب: ما هو بلازم، دعاء القنوت مستحب، لو رفع رأسه من الركعة الأخيرة الوتر، ثم سجد، ولم يقنت لا بأس، القنوت مستحب فقط، ما هو لازم، فلو فعله بعض الأحيان، وتركه بعض الأحيان، فلا بأس، القنوت مستحب، وليس بواجب، نعم.","link":"https://binbaz.org.sa/fatwas/14130/حكم-نسيان-القنوت-في-صلاة-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_570/57016.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":16363,"question":"علي صالح من جدة، يقول: هل هناك دعاء يقرأ في صلاة الفجر في الركعة الأخيرة بعد قراءة الفاتحة؟","title":"حكم الدعاء بعد الفاتحة في صلاة الفجر","answer":"الجواب: ليس هناك شيء، إنما بعد الفاتحة يقرأ ما تيسر من القرآن في جميع الصلوات، بعد الفاتحة يقرأ ما تيسر، في الظهر والعصر والمغرب والعشاء والفجر، الدعاء قبل، يستفتح قبل قراءة الفاتحة، إذا كبر تكبيرة الإحرام يستفتح: سبحانك اللهم وبحمدك، وتبارك اسمك وتعالى جدك، ولا إله غيرك أو بالاستفتاح الثاني: اللهم باعد بيني وبين خطاياي كما باعدت بين المشرق والمغرب، اللهم نقني من خطاياي كما ينقى الثوب الأبيض من الدنس، اللهم اغسلني من خطاياي بالثلج والماء والبرد وهناك استفتاحات أخرى جاءت عن النبي ﷺ.  أما بعد الفاتحة لا، بعد الفاتحة يقرأ ما تيسر، وإذا سكت قليلًا بعد الفاتحة حتى يقرأ المأموم الفاتحة؛ فلا بأس -إن شاء الله- نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15062/حكم-الدعاء-بعد-الفاتحة-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58113.mp3","categories":["القنوت في الصلاة"]},{"id":16405,"question":"وجهونا إلى القنوت في صلاة الفجر؟ وكيف يكون؟ ومتى؟ جزاكم الله خيرًا.","title":"كيف يكون القنوت في صلاة الفجر؟","answer":"الجواب: الصواب أن القنوت غير مشروع في صلاة الفجر، ولا في غيرها؛ إلا بسبب، أما ما يفعله بعض الناس من القنوت دائمًا في الفجر فهو قول بعض العلماء، ولكنه قول مرجوح؛ لعدم الدليل عليه، وإنما يشرع القنوت إذا كان لسبب، ويسمى: القنوت للنوازل، فإذا كان هناك سبب مثل تعدي بعض الكفار على بعض المسلمين؛ فيقنت للدعوة للمسلمين بالنصر، والتأييد، والدعوة على الكافرين بالخذلان والهزيمة، كما فعل النبي ﷺ في دعوته على قريش، ودعوته على الذين قتلوا القراء. فالمقصود: أن القنوت للنوازل أمر مشروع إذا اعتدي على المسلمين؛ فيقنت المسلمون ضد العدو، ويدعون للمسلمين بالنصر، والتأييد، والعاقبة الحميدة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15118/كيف-يكون-القنوت-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_755/nour_75502.mp3","categories":["القنوت في الصلاة"]},{"id":16468,"question":"هل هناك دعاء يقرأ في صلاة الفجر في الركعة الأخيرة بعد قراءة الفاتحة، وسورة بعدها؟ ما حكم هذا الدعاء؟","title":"هل هناك دعاء في الركعة الأخيرة من الفجر؟","answer":"الجواب: ليس له أصل، إذا فرغ من القراءة يركع، ليس هناك دعاء لا بعد الركوع، ولا قبل الركوع، والقنوت بعد الركوع في الفجر ضعيف، قال به بعض أهل العلم، ولكنه قول ضعيف، والصواب تركه. الصواب ليس فيها قنوت إلا عند النوازل، إذا جاء نوازل على المسلمين؛ قنت الإمام في الفجر وغيرها، كأن يحيط بهم العدو؛ فيقنت الإمام بعد الركوع في الفجر، أو في الظهر، أو في غيرها، يدعو على المشركين، ويدعو الله بنصر المسلمين، أما القنوت الذي يفعله بعض الناس دائمًا في الفجر، فهذا الصواب تركه. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15175/هل-هناك-دعاء-في-الركعة-الاخيرة-من-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_582/58207.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":16706,"question":"يسأل مع السائلين سماحة الشيخ عن حكم القنوت في صلاة الفجر؟","title":"ما حكم القنوت في صلاة الفجر؟","answer":"الجواب: لم يثبت عن النبي ﷺ في ذلك شيء، والأحاديث التي يذكرها بعض العلماء بأنه كان يقنت في الفجر ضعيفة، وقد حملها ابن القيم -لو صحت- على أن المراد بذلك طول الوقوف؛ لأن القنوت طول القيام وأنه ﷺ كان يطيل وقفته بعد الركوع بعض الشيء في الركعة الأخيرة للفجر، ولكن الأحاديث ضعيفة، وإنما كان يقنت في الوتر في قنوت الوتر، وهكذا كان يقنت في النوازل، إذا نزلت بالمسلمين نازلة؛ يقنت في الصبح، وفي غيرها، إذا نزل... حرب على المسلمين، أو أناس تعدوا عليهم من قطاع الطريق، أو غير ذلك؛ شرع القنوت في الفجر، وفي غيرها، نعم.  المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15457/ما-حكم-القنوت-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_761/nour_76105.mp3","categories":["القنوت في الصلاة"]},{"id":16985,"question":"سمعت أن القنوت ليس ضروريًا أداؤه باستمرار في صلاة الوتر، إلا أنني أرتاح في أدائه، فهل يجوز ذلك، أو لا؟","title":"هل القنوت مستحب في الوتر؟","answer":"الجواب: القنوت ليس بواجب، بل هو مستحب، فإذا تركه المؤمن أو المؤمنة بعض الأحيان؛ فلا بأس، ولكن استعماله دائمًا أولى وأفضل؛ لأن النبي ﷺ علم ابن بنته الحسن بن علي ذلك، علمه قنوت الوتر، ولم يقل له: في بعض الأحيان، بل علمه ما يدل على أنه يلازمه، ويفعله في جميع الأوقات، أن يقول: اللهم اهدني فيمن هديت .. إلى آخره، فكون الإنسان يأتي بالقنوت في الوتر في السنة كلها طيب على أصح أقوال العلماء، لا بأس، وإن ترك بعض الأحيان؛ فلا حرج. المقصود: أنه سنة ليس بواجب، والمحافظة عليه دائمًا أفضل، وأولى في ظاهر حديث الحسن بن علي، والصحابة يفعلونه تارة، ويتركونه تارة  فالأمر واسع -بحمد الله- لكن المحافظة عليه لظاهر الحديث الصحيح أولى وأفضل.  جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15797/هل-القنوت-مستحب-في-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_829/nour_82917.mp3","categories":["الوتر وقيام الليل","القنوت في الصلاة"]},{"id":17012,"question":"من اليمن السائل أحمد سالم يمني ومقيم بالرياض، يقول: سماحة الشيخ! هل يجوز القنوت في صلاة الفجر، أم لا، مع الدليل مأجورين؟","title":"هل القنوت في صلاة الفجر مشروع؟","answer":"الجواب: القنوت في صلاة الفجر غير مشروع، ولم يثبت عنه ﷺ القنوت في الفجر إلا في أحوال خاصة في الدعاء على المشركين في النوازل، كان يدعو في الفجر، وغيرها، أما القنوت المعتاد الدائم هذا لا أصل له، والأفضل تركه، والأحوط تركه، بعض أهل العلم يراه مستحبًا دائمًا، ولكن لا دليل عليه، والحديث الوارد في ذلك ضعيف، والأرجح أنه لا يشرع، هذا هو الأرجح، لكن إذا كان نوازل مثل عدو نزل بالمسلمين، فإذا دعا عليه المسلمون في الفجر، أو غيرها؛ فلا بأس، كما كان النبي يفعل، عليه الصلاة والسلام.","link":"https://binbaz.org.sa/fatwas/15800/هل-القنوت-في-صلاة-الفجر-مشروع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_587/58707.mp3","categories":["القنوت في الصلاة"]},{"id":17025,"question":"يقول: عندنا يقولون: دعاء القنوت في صلاة الصبح بصوت مرتفع، وأنا قرأت في كتاب فقه السنة للسيد سابق: أن القنوت في صلاة الصبح غير مشروع إلا في وقت النوازل يقنت فيه، وفي سائر الصلوات الخمس، ما الحكم في ذلك؟","title":"حكم القنوت في صلاة الفجر بصوت مرتفع","answer":"الجواب: الصواب مثل ما قال السيد سابق، مثل ما ذكرتم عن السيد سابق، السنة ألا يقنت في الفجر إلا عند النوازل، وهكذا بقية الصلوات في النوازل، إذا نزل بالمسلمين حادث حرب ونحوه؛ يقنت الإمام والمأمومون يسألون الله -جل وعلا- رفع ذلك، ودفع ذلك عن المسلمين، وأن ينصر دينه، ويعلي كلمته، كما كان النبي يقنت في النوازل، عليه الصلاة والسلام. أما المداومة على القنوت، كالقنوت في الصبح من غير سبب، هذا غير مشروع، قد ثبت عن سعد بن طارق بن أشيم أنه قال: قلت لأبي: \"يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر و عمر و عثمان وعلي، أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث\" رواه أبو داود، والترمذي، والنسائي، والإمام أحمد بإسناد جيد. المقصود: أن هذا هو السنة، السنة ترك القنوت في الفجر إلا في النوازل، إذا جاءت نازلة قنت في الفجر، وفي غيرها، كما فعل المسلمون في نازلة حرب الكويت لما احتلها حاكم العراق، وحصل بسبب ذلك ما حصل من الفتنة؛ قنت المسلمون في الصلوات حتى هزم الله العدو، وأذل أنفه، ورد البلاد إلى أهلها، ونصر الحق، وأهله، نسأل الله أن ينصر دينه، ويعلي كلمته. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15820/حكم-القنوت-في-صلاة-الفجر-بصوت-مرتفع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_830/nour_83008.mp3","categories":["القنوت في الصلاة"]},{"id":17113,"question":"يقول: بالنسبة لدعاء القنوت، هل هو وارد عن الرسول ﷺ؟ وما معنى: اللهم اهدنا فيمن هديت، وعافنا فيمن عافيت، وتولنا فيمن توليت؟","title":"حكم القنوت ومعنى قولنا: اللهم اهدنا فيمن هديت","answer":"الجواب: نعم، كان يقنت في النوازل -عليه الصلاة والسلام- إذا نزل بالمسلمين نازلة قنت في الدعاء على العدو، وعلم الحسن دعاء القنوت: اللهم اهدنا فيمن هديت وعافنا فيمن عافيت يعني: اللهم اهدنا في عبادك المهتدين، وعافنا في عبادك الذين عافيتهم، يسأل ربه أن يهديه ضمن المهديين، وأن يعافيه ضمن المعافين، وأن يرزقه البركة، نعم  فيما أعطاه وأن يتولاه. نعم. المقدم: جزاكم الله خيرًا يا شيخ.","link":"https://binbaz.org.sa/fatwas/15919/حكم-القنوت-ومعنى-قولنا-اللهم-اهدنا-فيمن-هديت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58910.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":17572,"question":"من أسئلة هذا السائل يقول: الدعاء بعد الركوع في الركعة الثانية من صلاة الفجر الدعاء بدعاء القنوت هل هو وارد؟","title":"الدعاء بدعاء القنوت هل هو وارد؟","answer":"الجواب: ورد في النوازل عند الحاجة، عند وجود النوازل إذا نزل بالمسلمين عدو، كان النبي ﷺ يقنت بعد الركوع الأخير في الفجر، وقنت في الصلوات الأخرى يدعو على الكفار، أما القنوت الدائم في الفجر لا هذا ما هو بصحيح ما هو بمشروع.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16495/الدعاء-بدعاء-القنوت-هل-هو-وارد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59408.mp3","categories":["القنوت في الصلاة"]},{"id":17593,"question":"من أسئلة هذا السائل يقول: الدعاء بعد الركوع في الركعة الثانية من صلاة الفجر الدعاء بدعاء القنوت هل هو وارد؟","title":"هل القنوت مشروع في صلاة الفجر؟","answer":"الجواب: ورد في النوازل عند الحاجة عند وجود النوازل إذا نزل بالمسلمين عدو، كان النبي ﷺ يقنت بعد الركوع الأخير في الفجر، وقنت في الصلوات الأخرى يدعو على الكفار، أما القنوت الدائم في الفجر لا هذا ما هو بصحيح ما هو بمشروع.\nالمقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/16512/هل-القنوت-مشروع-في-صلاة-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_594/59408.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":18211,"question":"رسالة بعث بها المستمع: عيد علي عبد المقصود الأعرج، أخونا بعث برسالة، وضمنها جمعًا من الأسئلة، في أحدها يقول: مسألة القنوت في الفجر، ألاحظ أن الناس يداومون عليها، فهل تجوز الصلاة خلف من يقنت كل يوم في صلاة الفجر؟ أو نصلي في المنزل؟ جزاكم الله خيرًا.","title":"جواز الصلاة خلف إمام يقنت في الفجر","answer":"الجواب: لا حرج في الصلاة معهم؛ لأن بعض أهل العلم قال ذلك، وله شبهة، فلا حرج، بل الواجب أن تصلي معهم، ولا تصلي في البيت، يجب أن تصلي مع المسلمين في الفجر، ولو قنت الإمام، لكن الصواب ترك القنوت، الأفضل ترك القنوت؛ لأن الأدلة الشرعية تدل على تركه، إلا في النوازل، إذا نزلت نازلة بالمسلمين، قنتوا بالدعاء على عدوهم، أما القنوت دائمًا، فالسنة تركه، لكن لو كان إمامك يقنت؛ لأن بعض أهل العلم يقول ذلك، فلا بأس، صل معهم. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17252/جواز-الصلاة-خلف-امام-يقنت-في-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_731/nour_73118.mp3","categories":["صلاة الجماعة","القنوت في الصلاة"]},{"id":18277,"question":"كثر الجدال في أمور الدعاء بعد الصلاة في الركعة الثانية من صلاة الصبح بعد الوقوف من الركوع، فهل يصح جهرًا، وهل يصح في جماعة، مع أني أسمع الدعاء جهرًا عندما تنقل صلاة الفجر في بعض الإذاعات، ويختمون دعاءهم بقولهم: بجاه النبي ﷺ وبسر الفاتحة، وضحوا لنا؟ جزاكم الله خيرًا.","title":"حكم الدعاء في الركعة الثانية من صلاة الصبح جهرا","answer":"الجواب: هذا يسمى (القنوت) بعد الركوع في الركعة الثانية من الفجر: اختلف فيه العلماء، فمنهم من قال: إنه يستحب هذا القنوت، ورأوه سنة مستمرة. وذهب آخرون من أهل العلم إلى أنه سنة في حق المسلمين إذا وقعت نازلة، إذا نزل بالمسلمين نازلة كمحاصرة عدو للمسلمين، أو نزول بلاء بالمسلمين فيدعو الإمام ويقنت، ويؤمن عليه المأمومون. وقال بعضهم: هذا يختص بولي الأمر، الإمام الأكبر -السلطان- هو الذي يفعل ذلك كما فعله النبي ﷺ في النوازل، فإنه ﷺ دعا على أحياء من العرب ثم ترك ذلك، وفعله مرات كثيرة ﷺ في النوازل، لا دائمًا، وهذا هو الصواب أنه يفعل في النوازل، لا دائمًا؛ لأنه ثبت عنه ﷺ: \"أنه قنت ودعا على أحياء من العرب\" من حديث ابن عمر، ومن حديث البراء بن عازب، ومن حديث أبي هريرة .. وجماعة من الصحابة، أخبروا عنه ﷺ أنه قنت يدعو على أحياء من العرب، ومنهم الذين قتلوا القراء السبعين دعا عليهم شهرًا ﷺ ودعا على جماعة من قريش، قبل الفتح، فهذا جائز بل مستحب إذا وجدت أسبابه. أما القنوت الدائم في صلاة الفجر بعد الركوع الثاني كما استحبه بعض أهل العلم، فهذا ليس بجيد، والصواب أنه لا يستحب في الفجر، ولا في غيرها، بصفة دائمة إنما يفعل للنوازل، إذا كان هناك نازلة تضر المسلمين قنت الإمام. أما اتخاذ القنوت في صلاة الفجر، بعد الركوع الثاني سنة دائمة، فهذا قول بعض أهل العلم كـالشافعية رحمهم الله وجماعة معهم، ولكنه قول مرجوح. الصواب: أنه لا يستحب؛ لأنه ثبت من حديث سعد بن طارق بن أشيم الأشجعي، قال: «قلت لأبي: يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر ، و عمر ، و عثمان ، و علي : أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث»، فهذا يدل على أنه ليس معروفًا في عهده ﷺ، ولا في عهد الخلفاء الراشدين في غير النوازل، ولهذا قال هذا الصحابي الجليل: إنه محدث يعني: الاستمرار عليه، والقنوت من دون أسباب، هذا هو الراجح، وهو الأقوى دليلًا. لكن لو صليت خلف إمام يقنت فلا حرج؛ لأنه له قول، وله شبهة، وقد جاء في بعض الأحاديث الضعيفة، فلو صليت خلفه فلا حرج عليك، ولو قنت معه وأمنت معه لا حرج؛ لأنه قنوت له شبهة، قال به بعض أهل العلم فالأمر فيه واسع، لكن السنة والأفضل ترك ذلك. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17326/حكم-الدعاء-في-الركعة-الثانية-من-صلاة-الصبح-جهرا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_910/nour_91013.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":18306,"question":"تقول: أنا عندما أصلي الشفع، وأوتر في بعض الأحيان، لا أدعو بعد الركوع من الوتر، فقط أسجد، ثم أسلم، هل صلاتي صحيحة؟ أم أن هناك غير ذلك؟ وهل يجوز لي أن أدعو بعد التشهد من الوتر، بدلًا من كوني أدعو بعد الركوع؟ أفتوني جزاكم الله خيرًا.","title":"هل يصح الوتر دون دعاء القنوت وحكم الدعاء قبل التسليم","answer":"الجواب: القنوت مستحب بالوتر، ليس بواجب، لكن يستحب لمن حفظه أن يقنت في الوتر بعد الركوع في الركعة الأخيرة، وهي الواحدة التي يوتر بها في أول الليل، أو في آخره، يقنت بقوله: اللهم اهدني فيمن هديت، وعافني فيمن عافيت.. إلى آخره؛ لأن الرسول ﷺ علمه ابن بنته الحسن، وتعليم النبي ﷺ لواحد، تعليم للجميع، فإذا تيسر ذلك فهو أفضل، وإلا فلا حرج، والحمد لله، فليس بواجب، وإذا دعا الإنسان بعد التشهد، قبل أن يسلم؛ فهذا مستحب أيضًا، الدعاء في آخر التحيات، قبل أن يسلم، النبي ﷺ علم الصحابة، لما علمهم التشهد قال ﷺ: ثم ليتخير من الدعاء أعجبه إليه فيدعو، وفي اللفظ الآخر: ثم ليختر من المسألة ما شاء. وكان النبي يدعو ﷺ في صلاته، في آخر التحيات، قبل أن يسلم، بعد التشهد، وبعد الصلاة على النبي ﷺ، يدعو، ويستحب أنه يقرأ التحيات، ثم يصلي على النبي ﷺ، ثم يستعيذ بالله من عذاب جهنم، ومن عذاب القبر، ومن فتنة المحيا والممات، ومن فتنة المسيح الدجال ، ثم يدعو بما يسر الله من الدعوات الطيبة، الواردة عن النبي ﷺ، مثل: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك، اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك، وارحمني، إنك أنت الغفور الرحيم، هذا دعاء عظيم. كذلك الدعاء بما ثبت عنه ﷺ في البخاري: اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، ومن عذاب القبر، كل هذا قبل السلام يستحب، قبل أن يسلم، يجتهد في الدعاء، ومن أفضل ذلك ما تقدم: اللهم أعني على ذكرك، وشكرك، وحسن عبادتك -للرجل والمرأة- اللهم إني ظلمت نفسي ظلمًا كثيرًا، ولا يغفر الذنوب إلا أنت، فاغفر لي مغفرةً من عندك، وارحمني، إنك أنت الغفور الرحيم، اللهم إني أعوذ بك من البخل، وأعوذ بك من الجبن، وأعوذ بك أن أرد إلى أرذل العمر، وأعوذ بك من فتنة الدنيا، وأعوذ بك من عذاب القبر. ومن الدعاء أيضًا في آخر الصلاة، قبل السلام: اللهم اغفر لي ما قدمت، وما أخرت، وما أسررت، وما أعلنت، وما أسرفت، وما أنت أعلم به مني، أنت المقدم، وأنت المؤخر، لا إله إلا أنت، كل هذا حسن، دعوات في آخر الصلاة قبل السلام، أما القنوت فهو مستحب في الوتر، في الركعة الأخيرة بعد الركوع، ومن تركه فلا حرج عليه. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/17355/هل-يصح-الوتر-دون-دعاء-القنوت-وحكم-الدعاء-قبل-التسليم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_732/nour_73203.mp3","categories":["الأدعية والأذكار","الوتر وقيام الليل","القنوت في الصلاة"]},{"id":18609,"question":"هل دعاء القنوت في رمضان محدد بدعاء معين، أو تجوز الزيادة فيه، وما هو الأفضل في دعاء القنوت وخصوصًا في رمضان؟","title":"الدعاء المشروع في قنوت الوتر","answer":"الجواب: دعاء القنوت على ما روي عن النبي ﷺ من حديث الحسن: اللهم اهدنا فيمن هديت... ويزيد فيه من الدعوات الطيبة ما يناسب، إذا دعا فيه بعض الدعوات الطيبة لا بأس، كما كان النبي ﷺ علم الحسن: اللهم اهدني فيمن هديت... وكما كان عمر -رضي الله عنه وأرضاه- يقنت: «اللهم إنا نستعينك ونستهديك» وكما قنت النبي ﷺ في النوازل إذا دعا بدعوات مع: اللهم! اهدنا فيمن هديت كله حسن -إن شاء الله- كما جرى للسلف ، نعم.","link":"https://binbaz.org.sa/fatwas/17713/الدعاء-المشروع-في-قنوت-الوتر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_918/nour_91818.mp3","categories":["القنوت في الصلاة","الوتر وقيام الليل"]},{"id":18986,"question":"في ثاني أسئلة هذا السائل من محافظة حضرموت يقول: سماحة الشيخ! بالنسبة لدعاء القنوت في صلاة الفجر، وهو الدعاء المعروف: اللهم اهدنا فيمن هديت... إلى آخره، هل ورد عن النبي ﷺ بأنه قنت؟","title":"ما صحة دعاء \"اللهم اهدنا فيمن هديت\" في القنوت؟","answer":"الجواب: كان النبي ﷺ يقنت في النوازل، إذا نزل بالمسلمين نازلة، عدو نزل بهم، وشدة؛ دعا لهم، في الفجر وغيرها، أما اعتياد بعض الناس القنوت في الفجر من دون سبب لا، ما هو بمشروع، في الحديث الصحيح عن سعد بن طارق الأشجعي قال: «قلت لأبي: يا أبت إنك قد صليت خلف رسول الله ﷺ وخلف أبي بكر وعمر وعثمان وعلي أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث» يعني: ما كان يقنتوا في الفجر، إلا إذا حدث حادث مثل عدو حاصر البلد، أو غزى المسلمين يدعى عليه في القنوت، في الفجر وفي غيره، القنوت في الفجر، في المغرب، في العشاء، في الظهر، في العصر يرفع يديه في الركعة الأخيرة بعد الركوع ويدعو على العدو، كما فعله النبي ﷺ في دعائه على المشركين. نعم. المقدم: سماحة الشيخ! حفظكم الله سائل يقول: هل نطلق على الإمام الذي يلزم هذا القنوت نقول: بأنه مبتدع، وأيضًا سؤالنا ما الرد على الذين يقولون بأنه سنة، ويستدلون بقوله تعالى: وَقَالَ رَبُّكُمُ ادْعُونِي أَسْتَجِبْ لَكُمْ[غافر:60] الآية، وأيضًا في قوله تعالى: وَقُومُوا لِلَّهِ قَانِتِينَ[البقرة:238] وبالحديث \"بأن الرسول ﷺ قنت إلى أن فارق الحياة\"؟ الشيخ: هذا يقال له: إن تركه أفضل ما يقال: بدعة ما يقال: مبتدع؛ لأن بعض أهل العلم يقول بذلك، بعض الأئمة مثل الشافعي وجماعة يرون القنوت في الفجر دائمًا، وهو قول ضعيف مرجوح، ولكن يعلم يقال هذا هو الأفضل. أما حديث \"لم يزل يقنت حتى فارق الدنيا\" فهو حديث ضعيف ليس بصحيح، وإنما قنت في الدعاء على المشركين.  أما القنوت دائمًا في الفجر من دون حاجة، لا ما هو مشروع إنما يشرع عند النوازل، عند وجود العدو في الفجر وغيره، ولكن من فعله استدلالًا ببعض الأحاديث الضعيفة فهذا يعلم أن السنة خلاف ذلك، ويبين له بالكلام الطيب، والأسلوب الحسن فقط. المقدم: شكر الله لكم -سماحة الشيخ- وبارك الله فيكم وفي علمكم، ونفع بكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/18145/ما-صحة-دعاء-اللهم-اهدنا-فيمن-هديت-في-القنوت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_792/nour_79211.mp3","categories":["الأدعية والأذكار","القنوت في الصلاة"]},{"id":19137,"question":"أخ لنا من اليمن الشمالي هو حمود محمد علي دلواح -فيما يبدو- أخونا يسأل عن القنوت، يقول: إن البعض يقنت لدينا في اليمن الشمالي، والبعض الآخر يقول: إنه بدعة، ما هو القول الراجح في هذا؟ جزاكم الله خيرًا.","title":"ما الراجح في قنوت الفجر؟","answer":"الجواب: القنوت السنة أن يكون في الوتر، وهكذا في النوازل، إذا نزل بالمسلمين نازلة مثل نزول الكفار على إخواننا في أفغانستان، وأشباههم، هذا يقنت لهم بالدعاء أن الله يعينهم، وأن الله يمنحهم التوفيق، وأن الله يسدد سهامهم، وأن الله ينصرهم على عدوهم. ويدعى على الأعداء بأن الله يهزم جمعهم ويشتت شملهم، هذا يقال له: قنوت النوازل، كما دعا النبي ﷺ على قريش لما صدته عن البيت، ودعا على قبائل من الكفار قتلوا بعض المسلمين، هذا لا بأس. أما القنوت الدائم في الصبح هذا الذي ينبغي تركه؛ لأن الأصل عدم شرعيته، وإنما القنوت في صلاة الوتر أو في النوازل، هذا هو المعروف، والحجة في ذلك ما ثبت عن سعد بن طارق بن أشيم الأشجعي رحمه الله أنه قال: \"قلت لأبي: يا أبت! إنك صليت خلف رسول الله ﷺ وخلف أبي بكر و عمر و عثمان و علي، أفكانوا يقنتون في الفجر؟ فقال: أي بني محدث\". خرجه الإمام أحمد و الترمذي و النسائي و ابن ماجة بإسناد صحيح ، فأخبر طارق أنه محدث، والمحدث بدعة. وذهب بعض أهل العلم إلى أنه لا بأس بذلك، واحتجوا بآثار وردت في ذلك، أن النبي ﷺ قنت في الصبح، ولكنها آثار ضعيفة، آثار ضعيفة ولو صحت لكانت محمولة على القنوت في النوازل، لا دائمًا، وهذا هو الأرجح، لكن لو صليت مع إنسان يقنت فلا بأس؛ لأنه متأول، وقد تبع جماعة من الأئمة رأوا ذلك، فإذا صليت معه فلا حرج في أن تقنت معه؛ لأن له شبهة ولأن له قول من أقوال العلماء قد اتبعه وأخذ به، فله شبهة، فإذا قنت وصليت معهم فلا حرج، ولكن ينصح هذا الإمام أنه لا يقنت إلا في النوازل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18351/ما-الراجح-في-قنوت-الفجر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_886/nour_88611.mp3","categories":["القنوت في الصلاة"]},{"id":19489,"question":"يقول هذا السائل من اليمن: أعلم بأن القنوت في صلاة الفجر أي: المداومة على ذلك ليس بمشروع، فنريد من سماحة الشيخ التفصيل في هذه المسألة، وما المقصود بالنوازل؟","title":"حكم القنوت في الفجر وفي النوازل","answer":"الجواب: القنوت في الفجر غير مشروع، ولا في غيره إلا في الوتر، إلا في النوازل إذا نزل بالمسلمين نازلة عدو نزل بهم لحربهم؛ فإن ولي الأمر يقنت في الصلاة في الفجر وغيرها يدعو عليهم بالهزيمة، ويدعو للمسلمين بالنصر كما فعله النبي ﷺ هذه النوازل، الحوادث التي تحدث من الأعداء ضد المسلمين، فالمسلمون يدعون ضد عدوهم يدعون الله بالنصر للمسلمين والهزيمة للكافرين. نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/18733/حكم-القنوت-في-الفجر-وفي-النوازل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93919.mp3","categories":["القنوت في الصلاة"]}]
